func SignManifest(manifest Manifest, issuedAt, expiresAt time.Time, rootPrivateKey ed25519.PrivateKey) (trust.Envelope, error) {
	if err := manifest.Validate(); err != nil {
		return trust.Envelope{}, err
	}
	payload, err := trust.EncodePayload(manifest)
	if err != nil {
		return trust.Envelope{}, err
	}
	if len(payload) > MaxManifestBytes {
		return trust.Envelope{}, fmt.Errorf("%w: manifest exceeds its size limit", ErrManifestInvalid)
	}
	scope := manifestScope(manifest.DeploymentID, string(manifest.Cell), manifest.Environment, manifest.ControllerRole, manifest.Slot)
	envelope, err := trust.Sign(payload, scope, issuedAt, expiresAt, rootPrivateKey)
	if err != nil {
		return trust.Envelope{}, err
	}
	if envelope.ExpiresAt.Sub(envelope.IssuedAt) > MaxManifestLifetime {
		return trust.Envelope{}, fmt.Errorf("%w: manifest validity exceeds %s", ErrManifestInvalid, MaxManifestLifetime)
	}
	if err := validateManifestEnvelopeSize(envelope); err != nil {
		return trust.Envelope{}, err
	}
	return envelope, nil
}

func VerifyManifest(envelope trust.Envelope, roots trust.Keyring, expected ManifestExpectation, now time.Time, policy trust.Policy) (VerifiedManifest, error) {
	if err := validateManifestEnvelopeSize(envelope); err != nil {
		return VerifiedManifest{}, err
	}
	if err := expected.validate(); err != nil {
		return VerifiedManifest{}, err
	}
	scope := manifestScope(expected.DeploymentID, string(expected.Cell), expected.Environment, "controller", expected.Slot)
	payload, err := trust.VerifyCurrent(envelope, scope, roots, now, policy)
	if err != nil {
		return VerifiedManifest{}, fmt.Errorf("verify bootstrap manifest signature: %w", err)
	}
	if len(payload) > MaxManifestBytes {
		return VerifiedManifest{}, fmt.Errorf("%w: manifest exceeds its size limit", ErrManifestInvalid)
	}
	manifest, digest, err := verifiedManifestPayload(envelope, payload, expected)
	if err != nil {
		return VerifiedManifest{}, err
	}
	verified := VerifiedManifest{
		manifest: cloneManifest(manifest), envelope: cloneEnvelope(envelope), digest: digest,
		issuedAt: envelope.IssuedAt, expiresAt: envelope.ExpiresAt, verified: true,
	}
	if manifest.PeerReceiptDelegation != nil {
		delegation, err := trust.VerifyDelegationCurrent(*manifest.PeerReceiptDelegation, roots, now, policy)
		if err != nil {
			return VerifiedManifest{}, fmt.Errorf("verify peer receipt delegation: %w", err)
		}
		if err := validatePeerDelegation(manifest, delegation); err != nil {
			return VerifiedManifest{}, err
		}
		verified.delegation = delegation
		verified.hasDelegation = true
	}
	return verified, nil
}

func verifiedManifestPayload(envelope trust.Envelope, payload []byte, expected ManifestExpectation) (Manifest, string, error) {
	manifest, err := ManifestPayload(payload)
	if err != nil {
		return Manifest{}, "", err
	}
	if manifest.DeploymentID != expected.DeploymentID || manifest.Environment != expected.Environment || manifest.ClusterID != expected.ClusterID ||
		manifest.Cell != expected.Cell || manifest.Slot != expected.Slot || manifest.ImageOCID != expected.ImageOCID ||
		manifest.StorageDomain != expected.StorageDomain ||
		!slices.Equal(manifest.ControllerSlots, expected.ControllerSlots) ||
		expected.IntentGeneration != 0 && manifest.IntentGeneration != expected.IntentGeneration ||
		expected.IntentSHA256 != "" && manifest.IntentSHA256 != expected.IntentSHA256 ||
		envelope.Scope.Role != manifest.ControllerRole || envelope.Scope.Slot != manifest.Slot {
		return Manifest{}, "", fmt.Errorf("%w: manifest does not match deployment expectation", ErrManifestInvalid)
	}
	digest, err := trust.Fingerprint(envelope)
	if err != nil {
		return Manifest{}, "", err
	}
	return manifest, digest, nil
}

func (manifest Manifest) Validate() error {
	return manifest.validateStructure(false)
}

func (manifest Manifest) validateStructure(derived bool) error {
	ociRegion, err := manifest.Cell.OCIRegion()
	if err != nil || manifest.SchemaVersion != ManifestSchemaVersion || !entityid.Valid(manifest.DeploymentID) ||
		!entityid.Valid(manifest.ClusterID) || manifest.Environment != "production" && manifest.Environment != "canary" ||
		manifest.OCIRegion != ociRegion || manifest.IntentGeneration == 0 || !sha256RE.MatchString(manifest.IntentSHA256) ||
		manifest.ControllerRole != "controller" || !controllerSlotRE.MatchString(manifest.Slot) || !controllerSlotRE.MatchString(manifest.SeedSlot) ||
		!slices.Contains(manifest.ControllerSlots, manifest.Slot) || !slices.Contains(manifest.ControllerSlots, manifest.SeedSlot) ||
		!isOCID(manifest.ImageOCID, "image") || manifest.ImageArchitecture != "linux-amd64" && manifest.ImageArchitecture != "linux-arm64" ||
		!sha256RE.MatchString(manifest.ReleaseReceiptSHA256) || len(manifest.ControllerSlots) == 0 || len(manifest.ControllerSlots) > 64 ||
		len(manifest.Profiles) != len(manifest.ControllerSlots) || len(manifest.Secrets) > 128 {
		return fmt.Errorf("%w: required manifest identity or binding field", ErrManifestInvalid)
	}
	if err := manifest.StorageDomain.Validate(); err != nil {
		return err
	}
	if len(manifest.ControllerConfig) == 0 || len(manifest.ControllerConfig) > MaxControllerConfigBytes ||
		!sha256RE.MatchString(manifest.ControllerConfigSHA256) ||
		digestBytes(manifest.ControllerConfig) != manifest.ControllerConfigSHA256 {
		return fmt.Errorf("%w: controller configuration bytes or digest", ErrManifestInvalid)
	}
	var config map[string]any
	if err := protocol.DecodeStrict(manifest.ControllerConfig, &config, MaxControllerConfigBytes); err != nil ||
		config["nats"] == nil || config["controller"] == nil {
		return fmt.Errorf("%w: controller configuration JSON", ErrManifestInvalid)
	}
	if len(manifest.ControllerFiles) != len(ControllerConfigFileNames) {
		return fmt.Errorf("%w: controller public sidecars are incomplete", ErrManifestInvalid)
	}
	for index, file := range manifest.ControllerFiles {
		if file.Name != ControllerConfigFileNames[index] || len(file.Bytes) == 0 ||
			len(file.Bytes) > MaxControllerSidecarBytes || !sha256RE.MatchString(file.SHA256) ||
			digestBytes(file.Bytes) != file.SHA256 {
			return fmt.Errorf("%w: controller public sidecar %d", ErrManifestInvalid, index)
		}
		var value map[string]any
		if err := protocol.DecodeStrict(file.Bytes, &value, MaxControllerSidecarBytes); err != nil || value == nil {
			return fmt.Errorf("%w: controller public sidecar JSON", ErrManifestInvalid)
		}
	}
	if manifest.ManagedMaterial != nil {
		if err := manifest.ManagedMaterial.Validate(); err != nil {
			return err
		}
	}
	if err := validateReleaseProofWires(manifest); err != nil {
		return err
	}
	if hasDuplicate(manifest.ControllerSlots) || !slices.IsSorted(manifest.ControllerSlots) {
		return fmt.Errorf("%w: controller slot list is duplicated or not sorted", ErrManifestInvalid)
	}
	profiles := make(map[string]struct{}, len(manifest.Profiles))
	for _, profile := range manifest.Profiles {
		if err := profile.validate(); err != nil {
			return err
		}
		if !slices.Contains(manifest.ControllerSlots, profile.Slot) {
			return fmt.Errorf("%w: launch profile slot is not authorized", ErrManifestInvalid)
		}
		if _, exists := profiles[profile.Slot]; exists {
			return fmt.Errorf("%w: duplicate launch profile slot", ErrManifestInvalid)
		}
		profiles[profile.Slot] = struct{}{}
	}
	for _, slot := range manifest.ControllerSlots {
		if _, exists := profiles[slot]; !exists {
			return fmt.Errorf("%w: controller slot has no launch profile", ErrManifestInvalid)
		}
	}
	secretFiles := make(map[string]struct{}, len(manifest.Secrets))
	for _, secret := range manifest.Secrets {
		if err := secret.validate(manifest); err != nil {
			return err
		}
		if _, exists := secretFiles[secret.TargetFile]; exists {
			return fmt.Errorf("%w: duplicate secret output file", ErrManifestInvalid)
		}
		secretFiles[secret.TargetFile] = struct{}{}
	}
	peerSlots := slices.DeleteFunc(slices.Clone(manifest.ControllerSlots), func(slot string) bool { return slot == manifest.SeedSlot })
	if derived && manifest.PeerReceiptDelegation != nil || !derived && (len(peerSlots) == 0 && manifest.PeerReceiptDelegation != nil || len(peerSlots) > 0 && manifest.PeerReceiptDelegation == nil) {
		return fmt.Errorf("%w: peer signer delegation must exactly match peer slot presence", ErrManifestInvalid)
	}
	payload, err := trust.EncodePayload(manifest)
	if err != nil {
		return fmt.Errorf("%w: encode manifest: %v", ErrManifestInvalid, err)
	}
	if len(payload) > MaxManifestBytes {
		return fmt.Errorf("%w: manifest exceeds its size limit", ErrManifestInvalid)
	}
	return nil
}

func validateReleaseProofWires(manifest Manifest) error {
	if len(manifest.ReleaseImageReceiptWire) == 0 || len(manifest.ReleaseImageReceiptWire) > MaxManifestBytes ||
		len(manifest.ReleaseDelegationWire) == 0 || len(manifest.ReleaseDelegationWire) > MaxManifestBytes {
		return fmt.Errorf("%w: required release proof wire is absent or exceeds the manifest limit", ErrManifestInvalid)
	}
	if _, err := trust.DecodeEnvelope(manifest.ReleaseImageReceiptWire); err != nil {
		return fmt.Errorf("%w: image receipt wire is not canonical: %v", ErrManifestInvalid, err)
	}
	if _, err := trust.DecodeEnvelope(manifest.ReleaseDelegationWire); err != nil {
		return fmt.Errorf("%w: release delegation wire is not canonical: %v", ErrManifestInvalid, err)
	}
	if digestBytes(manifest.ReleaseImageReceiptWire) != manifest.ReleaseReceiptSHA256 {
		return fmt.Errorf("%w: release image receipt wire does not match its exact-wire SHA-256 pin", ErrManifestInvalid)
	}
	return nil
}

func cloneManifest(manifest Manifest) Manifest {
	if manifest.ManagedMaterial != nil {
		manifest.ManagedMaterial = new(*manifest.ManagedMaterial)
	}
	manifest.ControllerSlots = slices.Clone(manifest.ControllerSlots)
	profiles := manifest.Profiles
	manifest.Profiles = make([]LaunchProfile, len(profiles))
	for index, profile := range profiles {
		manifest.Profiles[index] = cloneProfile(profile)
	}
	manifest.Secrets = slices.Clone(manifest.Secrets)
	manifest.ReleaseImageReceiptWire = bytes.Clone(manifest.ReleaseImageReceiptWire)
	manifest.ReleaseDelegationWire = bytes.Clone(manifest.ReleaseDelegationWire)
	manifest.ControllerConfig = bytes.Clone(manifest.ControllerConfig)
	manifest.ControllerFiles = slices.Clone(manifest.ControllerFiles)
	for index := range manifest.ControllerFiles {
		manifest.ControllerFiles[index].Bytes = bytes.Clone(manifest.ControllerFiles[index].Bytes)
	}
	if manifest.PeerReceiptDelegation != nil {
		delegation := cloneEnvelope(*manifest.PeerReceiptDelegation)
		manifest.PeerReceiptDelegation = &delegation
	}
	return manifest
}

func NewReceipt(manifest StartupAuthority, facts InstanceFacts) (Receipt, error) {
	if err := validateStartupAuthority(manifest); err != nil {
		return Receipt{}, err
	}
	return receiptForManifest(manifest.Manifest(), manifest.Digest(), facts)
}

// SignSeedReceipt creates a root-signed receipt for the exact seed instance.
func SignSeedReceipt(manifest VerifiedManifest, facts InstanceFacts, issuedAt, expiresAt time.Time, rootPrivateKey ed25519.PrivateKey) (trust.Envelope, error) {
	receipt, err := NewReceipt(manifest, facts)
	if err != nil {
		return trust.Envelope{}, err
	}
	if receipt.Slot != manifest.manifest.SeedSlot {
		return trust.Envelope{}, fmt.Errorf("%w: seed receipt is not for the manifest seed slot", ErrReceiptInvalid)
	}
	if !receiptIntervalWithinManifest(manifest, issuedAt, expiresAt) {
		return trust.Envelope{}, fmt.Errorf("%w: receipt validity exceeds its signed manifest", ErrReceiptInvalid)
	}
	return signReceipt(receipt, seedReceiptDomain, issuedAt, expiresAt, rootPrivateKey)
}

// SignPeerReceipt creates a founder-key-signed receipt only for a peer slot
// delegated by the root-signed manifest.
func SignPeerReceipt(manifest VerifiedManifest, facts InstanceFacts, issuedAt, expiresAt time.Time, founderPrivateKey ed25519.PrivateKey) (trust.Envelope, error) {
	receipt, err := NewReceipt(manifest, facts)
	if err != nil {
		return trust.Envelope{}, err
	}
	if !manifest.hasDelegation || receipt.Slot == manifest.manifest.SeedSlot {
		return trust.Envelope{}, fmt.Errorf("%w: peer receipt is not authorized for this manifest slot", ErrReceiptInvalid)
	}
	if !receiptIntervalWithinManifest(manifest, issuedAt, expiresAt) {
		return trust.Envelope{}, fmt.Errorf("%w: receipt validity exceeds its signed manifest", ErrReceiptInvalid)
	}
	if len(founderPrivateKey) != ed25519.PrivateKeySize {
		return trust.Envelope{}, fmt.Errorf("%w: invalid peer signer key", ErrReceiptInvalid)
	}
	keyID, err := trust.KeyID(founderPrivateKey.Public().(ed25519.PublicKey))
	if err != nil {
		return trust.Envelope{}, err
	}
	if keyID != manifest.delegation.SubjectKeyID() {
		return trust.Envelope{}, fmt.Errorf("%w: peer signer key differs from root delegation", ErrReceiptInvalid)
	}
	return signReceipt(receipt, peerReceiptDomain, issuedAt, expiresAt, founderPrivateKey)
}

// VerifySeedReceipt verifies root authorization and exact seed instance facts.
func VerifySeedReceipt(envelope trust.Envelope, manifest StartupAuthority, roots trust.Keyring, facts InstanceFacts, now time.Time, policy trust.Policy) (VerifiedReceipt, error) {
	if derived, ok := manifest.(DerivedStartupAuthority); ok {
		return verifyDerivedReceipt(envelope, derived, facts, true, now, policy)
	}
	legacy, ok := manifest.(VerifiedManifest)
	if !ok {
		return VerifiedReceipt{}, ErrReceiptInvalid
	}
	return verifyReceipt(envelope, legacy, roots, facts, seedReceiptDomain, now, policy)
}

// VerifyPeerReceipt verifies the root-delegated founder key and exact peer
// instance facts. A peer receipt cannot authorize the seed slot.
func VerifyPeerReceipt(envelope trust.Envelope, manifest StartupAuthority, facts InstanceFacts, now time.Time, policy trust.Policy) (VerifiedReceipt, error) {
	if derived, ok := manifest.(DerivedStartupAuthority); ok {
		return verifyDerivedReceipt(envelope, derived, facts, false, now, policy)
	}
	legacy, ok := manifest.(VerifiedManifest)
	if !ok || !legacy.hasDelegation {
		return VerifiedReceipt{}, fmt.Errorf("%w: manifest has no peer receipt delegation", ErrReceiptInvalid)
	}
	return verifyReceipt(envelope, legacy, nil, facts, peerReceiptDomain, now, policy)
}

func signReceipt(receipt Receipt, domain string, issuedAt, expiresAt time.Time, privateKey ed25519.PrivateKey) (trust.Envelope, error) {
	if err := receipt.validate(); err != nil {
		return trust.Envelope{}, err
	}
	payload, err := trust.EncodePayload(receipt)
	if err != nil {
		return trust.Envelope{}, err
	}
	scope := trust.Scope{
		Domain: domain, DeploymentID: receipt.DeploymentID, Cell: string(receipt.Cell),
		Environment: receipt.Environment, Role: receipt.Role, Slot: receipt.Slot,
	}
	return trust.Sign(payload, scope, issuedAt, expiresAt, privateKey)
}

func verifyReceipt(envelope trust.Envelope, manifest VerifiedManifest, roots trust.Keyring, facts InstanceFacts, domain string, now time.Time, policy trust.Policy) (VerifiedReceipt, error) {
	if err := validateVerifiedManifest(manifest); err != nil {
		return VerifiedReceipt{}, err
	}
	if err := validateFacts(manifest, facts); err != nil {
		return VerifiedReceipt{}, err
	}
	if domain == seedReceiptDomain && facts.Slot != manifest.manifest.SeedSlot {
		return VerifiedReceipt{}, fmt.Errorf("%w: seed receipt targets a peer slot", ErrReceiptInvalid)
	}
	if domain == peerReceiptDomain && facts.Slot == manifest.manifest.SeedSlot {
		return VerifiedReceipt{}, fmt.Errorf("%w: peer receipt targets the seed slot", ErrReceiptInvalid)
	}
	scope := trust.Scope{
		Domain: domain, DeploymentID: manifest.manifest.DeploymentID, Cell: string(manifest.manifest.Cell),
		Environment: manifest.manifest.Environment, Role: manifest.manifest.ControllerRole, Slot: facts.Slot,
	}
	var payload []byte
	var err error
	if domain == seedReceiptDomain {
		payload, err = trust.VerifyCurrent(envelope, scope, roots, now, policy)
	} else {
		payload, err = trust.VerifyDelegatedCurrent(envelope, scope, manifest.delegation, now, policy)
	}
	if err != nil {
		return VerifiedReceipt{}, fmt.Errorf("verify bootstrap instance receipt: %w", err)
	}
	if envelope.IssuedAt.Before(manifest.issuedAt) || envelope.ExpiresAt.After(manifest.expiresAt) {
		return VerifiedReceipt{}, fmt.Errorf("%w: receipt validity exceeds its signed manifest", ErrReceiptInvalid)
	}
	if len(payload) > MaxReceiptBytes {
		return VerifiedReceipt{}, fmt.Errorf("%w: receipt exceeds its size limit", ErrReceiptInvalid)
	}
	want, err := NewReceipt(manifest, facts)
	if err != nil {
		return VerifiedReceipt{}, err
	}
	receipt, err := matchReceiptPayload(payload, want)
	if err != nil {
		return VerifiedReceipt{}, err
	}
	if envelope.Scope != scope {
		return VerifiedReceipt{}, fmt.Errorf("%w: signed receipt does not match exact instance facts", ErrIdentityMismatch)
	}
	return VerifiedReceipt{
		receipt: receipt, manifestDigest: manifest.digest,
		issuedAt: envelope.IssuedAt, expiresAt: envelope.ExpiresAt, verified: true,
	}, nil
}

type memorySecretReader struct {
	bundle   SecretBundle
	err      error
	calls    int
	secretID string
	version  int64
}

func (reader *memorySecretReader) GetSecretBundle(_ context.Context, secretID string, version int64) (SecretBundle, error) {
	reader.calls++
	reader.secretID = secretID
	reader.version = version
	return reader.bundle, reader.err
}

type advancingSecretReader struct {
	bundle    SecretBundle
	afterRead func()
	calls     int
}

func (reader *advancingSecretReader) GetSecretBundle(context.Context, string, int64) (SecretBundle, error) {
	reader.calls++
	if reader.afterRead != nil {
		reader.afterRead()
	}
	return reader.bundle, nil
}

func (vault *Vault) Materialize(ctx context.Context, manifest StartupAuthority, receipt VerifiedReceipt, reference SecretReference, destinationDirectory string) error {
	return vault.materialize(ctx, manifest, receipt, reference, destinationDirectory, nil)
}

// MaterializeCurrent additionally rechecks the whole current bootstrap proof
// immediately before the Vault request and before installing its response.
func (vault *Vault) MaterializeCurrent(ctx context.Context, manifest StartupAuthority, receipt VerifiedReceipt,
	reference SecretReference, destinationDirectory string, verifyCurrent func(time.Time) error,
) error {
	if verifyCurrent == nil {
		return ErrMaterialization
	}
	return vault.materialize(ctx, manifest, receipt, reference, destinationDirectory, verifyCurrent)
}

func (vault *Vault) materialize(ctx context.Context, manifest StartupAuthority, receipt VerifiedReceipt,
	reference SecretReference, destinationDirectory string, verifyCurrent func(time.Time) error,
) error {
	if vault == nil || vault.reader == nil {
		return errors.New("bootstrap Vault reader is not configured")
	}
	clock := time.Now
	if vault.now != nil {
		clock = vault.now
	}
	now := clock()
	if verifyCurrent != nil {
		if err := verifyCurrent(now); err != nil {
			return fmt.Errorf("current bootstrap proof before Vault read: %w", err)
		}
	}
	if err := authorizeSecretMaterialization(manifest, receipt, reference, now); err != nil {
		return err
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	bundle, err := vault.reader.GetSecretBundle(ctx, reference.SecretOCID, reference.VersionNumber)
	if err != nil {
		return fmt.Errorf("get exact OCI Vault secret bundle: %w", err)
	}
	now = clock()
	if verifyCurrent != nil {
		if err := verifyCurrent(now); err != nil {
			return fmt.Errorf("current bootstrap proof before secret install: %w", err)
		}
	}
	if err := authorizeSecretMaterialization(manifest, receipt, reference, now); err != nil {
		return err
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	content, err := decodeSecretBundle(bundle, reference)
	if err != nil {
		return err
	}
	defer clear(content)
	if err := materializeSecret(destinationDirectory, reference.TargetFile, content); err != nil {
		return err
	}
	return nil
}

func authorizeSecretMaterialization(manifest StartupAuthority, receipt VerifiedReceipt, reference SecretReference, now time.Time) error {
	if err := validateStartupAuthority(manifest); err != nil {
		return err
	}
	payload := manifest.Manifest()
	if !receipt.verified || !now.Before(receipt.expiresAt) || !now.Before(manifest.ExpiresAt()) ||
		receipt.manifestDigest != manifest.Digest() || receipt.receipt.ManifestDigest != manifest.Digest() ||
		receipt.receipt.DeploymentID != payload.DeploymentID || receipt.receipt.Environment != payload.Environment ||
		receipt.receipt.ClusterID != payload.ClusterID || receipt.receipt.Cell != payload.Cell ||
		receipt.receipt.OCIRegion != payload.OCIRegion || receipt.receipt.IntentGeneration != payload.IntentGeneration ||
		receipt.receipt.ManifestIntentSHA256 != payload.IntentSHA256 || receipt.receipt.Role != payload.ControllerRole ||
		receipt.receipt.Slot != payload.Slot {
		return fmt.Errorf("%w: secret retrieval requires a current receipt for this manifest and exact instance slot", ErrReceiptInvalid)
	}
	if err := reference.validate(payload); err != nil {
		return err
	}
	if !slices.Contains(payload.Secrets, reference) {
		return fmt.Errorf("%w: secret reference is not present in the signed manifest", ErrManifestInvalid)
	}
	switch reference.Purpose {
	case SecretRegionalShared, SecretHostIssuer, SecretControllerIssuer:
		return nil
	case SecretSeedFounder, SecretSeedLedgerSigner:
		if receipt.receipt.Slot != payload.SeedSlot {
			return fmt.Errorf("%w: seed signer secret requires the exact seed receipt", ErrReceiptInvalid)
		}
	case SecretController:
		if reference.Slot != receipt.receipt.Slot {
			return fmt.Errorf("%w: controller secret is bound to a different slot", ErrReceiptInvalid)
		}
	case SecretInterRegion:
		if reference.Slot != "" && reference.Slot != receipt.receipt.Slot {
			return fmt.Errorf("%w: Link TLS secret is bound to a different slot", ErrReceiptInvalid)
		}
	default:
		return fmt.Errorf("%w: unknown secret purpose", ErrManifestInvalid)
	}
	return nil
}

func decodeSecretBundle(bundle SecretBundle, reference SecretReference) ([]byte, error) {
	maxEncoded := base64.StdEncoding.EncodedLen(int(reference.MaxBytes))
	if bundle.SecretOCID != reference.SecretOCID || bundle.VersionNumber != reference.VersionNumber ||
		bundle.ContentType != "BASE64" || len(bundle.ContentBase64) == 0 || len(bundle.ContentBase64) > maxEncoded {
		return nil, ErrVaultSecretMismatch
	}
	content, err := base64.StdEncoding.Strict().DecodeString(bundle.ContentBase64)
	if err != nil || int64(len(content)) > reference.MaxBytes ||
		base64.StdEncoding.EncodeToString(content) != bundle.ContentBase64 || digestBytes(content) != reference.SHA256 {
		clear(content)
		return nil, ErrVaultSecretMismatch
	}
	return content, nil
}

func materializeSecret(directory, target string, content []byte) error {
	return materializeSecretWith(directory, target, content, func(writer io.Writer, value []byte) error {
		written, err := writer.Write(value)
		if err != nil {
			return err
		}
		if written != len(value) {
			return io.ErrShortWrite
		}
		return nil
	})
}

func materializeSecretWith(directory, target string, content []byte, write func(io.Writer, []byte) error) error {
	if !filepath.IsAbs(directory) || !fileNameRE.MatchString(target) || strings.Contains(target, "..") || write == nil {
		return fmt.Errorf("%w: destination must be an absolute directory and a simple file name", ErrMaterialization)
	}
	info, err := os.Lstat(directory)
	if err != nil {
		return fmt.Errorf("%w: inspect destination directory: %v", ErrMaterialization, err)
	}
	if !info.IsDir() || info.Mode()&os.ModeSymlink != 0 {
		return fmt.Errorf("%w: destination must be a non-symlink directory", ErrMaterialization)
	}
	root, err := os.OpenRoot(directory)
	if err != nil {
		return fmt.Errorf("%w: open destination directory: %v", ErrMaterialization, err)
	}
	defer root.Close()
	rootInfo, err := root.Stat(".")
	if err != nil || !rootInfo.IsDir() {
		return fmt.Errorf("%w: opened destination is not a directory", ErrMaterialization)
	}
	var temporary string
	var file *os.File
	for range 8 {
		var nonce [16]byte
		if _, err := rand.Read(nonce[:]); err != nil {
			return fmt.Errorf("%w: generate temporary name: %v", ErrMaterialization, err)
		}
		temporary = ".ts-secret-" + hex.EncodeToString(nonce[:]) + ".tmp"
		file, err = root.OpenFile(temporary, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
		if err == nil {
			break
		}
		if !errors.Is(err, os.ErrExist) {
			return fmt.Errorf("%w: create temporary file: %v", ErrMaterialization, err)
		}
	}
	if file == nil {
		return fmt.Errorf("%w: could not reserve a unique temporary file", ErrMaterialization)
	}
	defer root.Remove(temporary)
	if err := file.Chmod(0o600); err != nil {
		_ = file.Close()
		return fmt.Errorf("%w: set temporary file mode: %v", ErrMaterialization, err)
	}
	if err := write(file, content); err != nil {
		_ = file.Close()
		return fmt.Errorf("%w: write temporary file: %v", ErrMaterialization, err)
	}
	if err := file.Sync(); err != nil {
		_ = file.Close()
		return fmt.Errorf("%w: sync temporary file: %v", ErrMaterialization, err)
	}
	if err := file.Close(); err != nil {
		return fmt.Errorf("%w: close temporary file: %v", ErrMaterialization, err)
	}
	if err := root.Link(temporary, target); err != nil {
		return fmt.Errorf("%w: atomically install without overwrite: %v", ErrMaterialization, err)
	}
	directoryFile, err := root.Open(".")
	if err != nil {
		return fmt.Errorf("%w: open destination directory for sync: %v", ErrMaterialization, err)
	}
	if err := directoryFile.Sync(); err != nil {
		_ = directoryFile.Close()
		return fmt.Errorf("%w: sync destination directory: %v", ErrMaterialization, err)
	}
	if err := directoryFile.Close(); err != nil {
		return fmt.Errorf("%w: close destination directory: %v", ErrMaterialization, err)
	}
	return nil
}

