func NewLedger(client ObjectStorageClient, config LedgerConfig) (*Ledger, error) {
	return newLedger(client, config, false)
}

// NewHistoricalLedger constructs an evidence-only reader for the current
// five-domain ledger grant. Its write paths remain
// disabled even if the caller later invokes a mutation method.
func NewHistoricalLedger(client ObjectStorageClient, config LedgerConfig) (*Ledger, error) {
	return newLedger(client, config, true)
}

func newLedger(client ObjectStorageClient, config LedgerConfig, historical bool) (*Ledger, error) {
	if client == nil || validateLedgerAnchor(config) != nil || !ledgerIDPattern.MatchString(config.Namespace) ||
		!ledgerNamePattern.MatchString(config.Bucket) || !strings.HasPrefix(config.KMSKeyID, "ocid1.key.") ||
		len(config.KMSKeyID) > 255 || strings.ContainsAny(config.KMSKeyID, " \t\r\n") || !validLedgerPrefix(config.Prefix) ||
		!ledgerNamePattern.MatchString(config.HeadBucket) || config.HeadBucket == config.Bucket ||
		!strings.HasPrefix(config.HeadKMSKeyID, "ocid1.key.") || len(config.HeadKMSKeyID) > 255 ||
		strings.ContainsAny(config.HeadKMSKeyID, " \t\r\n") ||
		!ledgerIDPattern.MatchString(config.Environment) || config.TrustPolicy.MaxLifetime <= 0 || config.TrustPolicy.ClockSkew < 0 ||
		len(config.ControllerSlots) == 0 || len(config.ControllerSlots) > 64 || hasDuplicate(config.ControllerSlots) ||
		len(config.TrustRoots) == 0 && len(config.Delegations) == 0 || validateLedgerDelegations(config) != nil {
		return nil, errors.New("bootstrap ledger requires separate immutable and coordination buckets, KMS keys, environment, trust policy, and a valid Object Storage client")
	}
	for _, slot := range config.ControllerSlots {
		if !controllerSlotRE.MatchString(slot) {
			return nil, errors.New("bootstrap ledger requires a canonical anchor-pinned controller slot set")
		}
	}
	roots := make(trust.Keyring, len(config.TrustRoots))
	for keyID, key := range config.TrustRoots {
		roots[keyID] = bytes.Clone(key)
	}
	config.TrustRoots = roots
	config.Delegations = slices.Clone(config.Delegations)
	if config.DerivedStartup != nil {
		config.DerivedStartup = new(*config.DerivedStartup)
	}
	config.ControllerSlots = slices.Clone(config.ControllerSlots)
	if config.VerificationNow == nil {
		config.VerificationNow = time.Now
	}
	return &Ledger{client: client, config: config, maxRecord: maxLedgerRecordBytes, readOnly: historical}, nil
}

func validateLedgerDelegations(config LedgerConfig) error {
	if config.DerivedStartup != nil {
		authority := *config.DerivedStartup
		manifest := authority.Manifest()
		if authority.verifyStartupAuthority() != nil || manifest.DeploymentID != config.DeploymentID || manifest.Environment != config.Environment || manifest.ClusterID != config.ClusterID || manifest.Cell != config.Cell || manifest.StorageDomain != config.storageDomain() || !slices.Equal(manifest.ControllerSlots, config.ControllerSlots) || manifest.IntentGeneration != config.InitialRegionIntentGeneration || manifest.IntentSHA256 != config.InitialRegionIntentSHA256 {
			return ErrRecordAuthorization
		}
		if authority.template.startupIdentity().InitialSourceRegistration != nil {
			if len(config.Delegations) != 0 {
				return ErrRecordAuthorization
			}
			return nil
		}
	}
	if len(config.Delegations) != 1 {
		return errors.New("bootstrap ledger requires exactly one anchor-verified ledger delegation")
	}
	wantDomains := BootstrapLedgerCapabilityDomains()
	capabilities := config.Delegations[0].Capabilities()
	if len(capabilities) != len(wantDomains) {
		return fmt.Errorf("bootstrap ledger delegation must contain exactly %d record grants", len(wantDomains))
	}
	seen := make(map[string]struct{}, len(capabilities))
	for _, capability := range capabilities {
		if !slices.Contains(wantDomains, capability.Domain) || capability.DeploymentID != config.DeploymentID ||
			capability.Cell != string(config.Cell) || capability.Environment != config.Environment || capability.Role != roleController ||
			!sameStrings(capability.Slots, config.ControllerSlots) || !slices.Equal(capability.Actions, []string{"sign"}) {
			return errors.New("bootstrap ledger delegation does not match the exact anchored scope and slots")
		}
		if _, exists := seen[capability.Domain]; exists {
			return errors.New("bootstrap ledger delegation duplicates a signing domain")
		}
		seen[capability.Domain] = struct{}{}
	}
	return nil
}

func validateInstancePrincipalLedgerConfig(config LedgerConfig) error {
	// Keep this pre-authentication check aligned with NewLedger's config check.
	// NewLedger remains authoritative after the SDK client is constructed.
	if validateLedgerAnchor(config) != nil || !ledgerIDPattern.MatchString(config.Namespace) ||
		!ledgerNamePattern.MatchString(config.Bucket) || !strings.HasPrefix(config.KMSKeyID, "ocid1.key.") ||
		len(config.KMSKeyID) > 255 || strings.ContainsAny(config.KMSKeyID, " \t\r\n") || !validLedgerPrefix(config.Prefix) ||
		!ledgerNamePattern.MatchString(config.HeadBucket) || config.HeadBucket == config.Bucket ||
		!strings.HasPrefix(config.HeadKMSKeyID, "ocid1.key.") || len(config.HeadKMSKeyID) > 255 ||
		strings.ContainsAny(config.HeadKMSKeyID, " \t\r\n") || !ledgerIDPattern.MatchString(config.Environment) ||
		config.TrustPolicy.MaxLifetime <= 0 || config.TrustPolicy.ClockSkew < 0 ||
		len(config.ControllerSlots) == 0 || len(config.ControllerSlots) > 64 || hasDuplicate(config.ControllerSlots) ||
		len(config.TrustRoots) == 0 && len(config.Delegations) == 0 || validateLedgerDelegations(config) != nil {
		return errors.New("bootstrap ledger configuration is invalid before Instance Principal setup")
	}
	for _, slot := range config.ControllerSlots {
		if !controllerSlotRE.MatchString(slot) {
			return errors.New("bootstrap ledger configuration has an invalid anchor-pinned controller slot set")
		}
	}
	return nil
}

func (ledger *Ledger) signedPayload(body []byte, scope BootstrapScope, domain string, current bool) (trust.Envelope, []byte, error) {
	envelope, err := trust.DecodeEnvelope(body)
	if err != nil {
		return trust.Envelope{}, nil, fmt.Errorf("%w: decode signed envelope: %v", ErrInvalidRecord, err)
	}
	expected := trust.Scope{
		Domain: domain, DeploymentID: scope.DeploymentID, Cell: scope.Cell,
		Environment: ledger.config.Environment, Role: roleController, Slot: scope.Slot,
	}
	if envelope.Scope != expected {
		return trust.Envelope{}, nil, fmt.Errorf("%w: signed scope mismatch", ErrRecordAuthorization)
	}
	now := ledger.now()
	verify := func() ([]byte, error) {
		if authority := ledger.config.DerivedStartup; authority != nil && slices.Contains(BootstrapLedgerCapabilityDomains(), domain) && slices.Contains(ledger.config.ControllerSlots, scope.Slot) {
			keyID, _ := trust.KeyID(authority.ledgerKey)
			keys := trust.Keyring{keyID: authority.ledgerKey}
			if current {
				if payload, err := trust.VerifyCurrent(envelope, expected, keys, now, ledger.config.TrustPolicy); err == nil && !envelope.IssuedAt.Before(authority.IssuedAt()) && !envelope.ExpiresAt.After(authority.ExpiresAt()) {
					return payload, nil
				}
			} else if payload, err := trust.VerifyHistorical(envelope, expected, keys, ledger.config.TrustPolicy); err == nil && !envelope.IssuedAt.Before(authority.IssuedAt()) && !envelope.ExpiresAt.After(authority.ExpiresAt()) {
				return payload, nil
			}
		}
		if current {
			if payload, err := trust.VerifyCurrent(envelope, expected, ledger.config.TrustRoots, now, ledger.config.TrustPolicy); err == nil {
				return payload, nil
			}
			for _, delegation := range ledger.config.Delegations {
				if payload, err := trust.VerifyDelegatedCurrent(envelope, expected, delegation, now, ledger.config.TrustPolicy); err == nil {
					return payload, nil
				}
			}
		} else {
			if payload, err := trust.VerifyHistorical(envelope, expected, ledger.config.TrustRoots, ledger.config.TrustPolicy); err == nil {
				return payload, nil
			}
			for _, delegation := range ledger.config.Delegations {
				if payload, err := trust.VerifyDelegatedHistorical(envelope, expected, delegation, ledger.config.TrustPolicy); err == nil {
					return payload, nil
				}
			}
		}
		return nil, ErrRecordAuthorization
	}
	payload, err := verify()
	if err != nil {
		return trust.Envelope{}, nil, fmt.Errorf("%w: domain %s", err, domain)
	}
	return envelope, payload, nil
}

func (ledger *Ledger) decodeIntent(scope BootstrapScope, body []byte, current bool) (Intent, trust.Envelope, error) {
	envelope, payload, err := ledger.signedPayload(body, scope, domainBootstrapIntent, current)
	if err != nil {
		return Intent{}, trust.Envelope{}, err
	}
	var intent Intent
	if err := decodeCanonicalPayload(payload, &intent); err != nil || !intent.matches(scope, ledger.config.Environment) {
		return Intent{}, trust.Envelope{}, fmt.Errorf("%w: intent payload does not match signed scope", ErrInvalidRecord)
	}
	if err := validateIntent(intent); err != nil {
		return Intent{}, trust.Envelope{}, err
	}
	if !intent.CreatedAt.Equal(envelope.IssuedAt) {
		return Intent{}, trust.Envelope{}, fmt.Errorf("%w: signed creation time differs from envelope issue time", ErrInvalidRecord)
	}
	if intent.RegionIntentGeneration != ledger.config.InitialRegionIntentGeneration ||
		intent.RegionIntentDigest != ledger.config.InitialRegionIntentSHA256 {
		return Intent{}, trust.Envelope{}, fmt.Errorf("%w: signed intent does not match the anchor-pinned initial region intent", ErrRecordAuthorization)
	}
	return intent, envelope, nil
}

func (ledger *Ledger) decodeResult(scope BootstrapScope, body []byte, current bool) (Result, error) {
	envelope, payload, err := ledger.signedPayload(body, scope, domainBootstrapResult, current)
	if err != nil {
		return Result{}, err
	}
	var result Result
	if err := decodeCanonicalPayload(payload, &result); err != nil || !result.matches(scope, ledger.config.Environment) {
		return Result{}, fmt.Errorf("%w: result payload does not match signed scope", ErrInvalidRecord)
	}
	if result.SchemaVersion != 1 || result.Mode != IntentModeManaged && result.Mode != IntentModeExternalSeed ||
		result.Attempt == 0 || result.Generation == 0 || result.RegionIntentGeneration == 0 || !validDigest(result.IntentDigest) ||
		!isOCID(result.InstanceOCID, "instance") || result.ETag == "" || !validOCIRegion(result.OCIRegion) ||
		!isOCID(result.CompartmentOCID, "compartment") || !isOCID(result.ImageOCID, "image") || result.Shape == "" ||
		!validDigest(result.ObservedProfileDigest) || !createTokenPattern.MatchString(result.CreateKey) || result.ObservedAt.IsZero() ||
		result.ObservedAt.Location() != time.UTC {
		return Result{}, fmt.Errorf("%w: result omits positive OCI identity or observation", ErrInvalidRecord)
	}
	if result.Mode == IntentModeManaged && (!validDigest(result.PeerReceiptDigest) || result.SeedReceiptDigest != "") ||
		result.Mode == IntentModeExternalSeed && (result.PeerReceiptDigest != "" || !validDigest(result.SeedReceiptDigest)) {
		return Result{}, fmt.Errorf("%w: result receipt binding does not match its mode", ErrInvalidRecord)
	}
	if result.ObservedAt.After(envelope.IssuedAt.Add(ledger.config.TrustPolicy.ClockSkew)) {
		return Result{}, fmt.Errorf("%w: result observation time is after its signed issue time", ErrInvalidRetryClock)
	}
	return result, nil
}

func (ledger *Ledger) decodeHead(scope BootstrapScope, body []byte, current bool) (SlotHead, error) {
	_, payload, err := ledger.signedPayload(body, scope, domainBootstrapHead, current)
	if err != nil {
		return SlotHead{}, err
	}
	var head SlotHead
	if err := decodeCanonicalPayload(payload, &head); err != nil || !head.matches(scope, ledger.config.Environment) {
		return SlotHead{}, fmt.Errorf("%w: HEAD payload does not match signed scope", ErrInvalidRecord)
	}
	if head.SchemaVersion != 1 || head.Attempt == 0 || head.Generation == 0 || !validDigest(head.IntentDigest) ||
		(head.ResultDigest != "" && !validDigest(head.ResultDigest)) {
		return SlotHead{}, fmt.Errorf("%w: malformed slot HEAD", ErrInvalidRecord)
	}
	if head.CandidateDigest != "" && !validDigest(head.CandidateDigest) ||
		head.PreviousCandidateDigest != "" && !validDigest(head.PreviousCandidateDigest) {
		return SlotHead{}, fmt.Errorf("%w: malformed candidate binding in slot HEAD", ErrInvalidRecord)
	}
	if head.Attempt == 1 {
		if head.Generation != 1 || head.PreviousAttempt != 0 || head.PreviousGeneration != 0 ||
			head.PreviousIntentDigest != "" || head.PreviousResultDigest != "" ||
			head.PreviousCandidateDigest != "" || head.RetirementDigest != "" {
			return SlotHead{}, fmt.Errorf("%w: initial slot HEAD has predecessor fields", ErrInvalidRecord)
		}
	} else if head.PreviousAttempt+1 != head.Attempt || head.PreviousGeneration+1 != head.Generation ||
		!validDigest(head.PreviousIntentDigest) || !validDigest(head.PreviousResultDigest) || !validDigest(head.RetirementDigest) {
		return SlotHead{}, fmt.Errorf("%w: advanced slot HEAD has invalid predecessor fields", ErrInvalidRecord)
	}
	return head, nil
}

func (ledger *Ledger) decodeManagedPeerCandidate(scope BootstrapScope, body []byte,
	current bool,
) (ManagedPeerCandidate, trust.Envelope, error) {
	envelope, payload, err := ledger.signedPayload(body, scope, domainBootstrapCandidate, current)
	if err != nil {
		return ManagedPeerCandidate{}, trust.Envelope{}, err
	}
	var candidate ManagedPeerCandidate
	if err := decodeCanonicalPayload(payload, &candidate); err != nil || !candidate.matches(scope, ledger.config.Environment) ||
		candidate.SchemaVersion != 1 || candidate.Attempt == 0 || candidate.Generation == 0 ||
		!validDigest(candidate.IntentDigest) || !createTokenPattern.MatchString(candidate.CreateKey) ||
		!validDigest(candidate.FounderPlanSHA256) || !validDigest(candidate.PeerRowDigest) ||
		!validDigest(candidate.ManifestDigest) || !validDigest(candidate.LaunchProfileDigest) ||
		!isOCID(candidate.InstanceOCID, "instance") {
		return ManagedPeerCandidate{}, trust.Envelope{}, fmt.Errorf("%w: managed-peer candidate is malformed or outside its signed scope", ErrInvalidRecord)
	}
	return candidate, envelope, nil
}

func (candidate ManagedPeerCandidate) matches(scope BootstrapScope, environment string) bool {
	return candidate.DeploymentID == scope.DeploymentID && candidate.Cell == scope.Cell &&
		candidate.Environment == environment && candidate.Role == roleController && candidate.Slot == scope.Slot
}

func validateManagedPeerCandidateForIntent(candidate ManagedPeerCandidate, intent Intent, intentDigest,
	founderPlanDigest, peerRowDigest, manifestDigest string,
) error {
	if intent.Mode != IntentModeManaged || intent.SchemaVersion != 1 || candidate.DeploymentID != intent.DeploymentID ||
		candidate.Cell != intent.Cell || candidate.Environment != intent.Environment || candidate.Role != intent.Role ||
		candidate.Slot != intent.Slot || candidate.Attempt != intent.Attempt || candidate.Generation != intent.Generation ||
		candidate.IntentDigest != intentDigest || candidate.CreateKey != intent.CreateKey ||
		candidate.FounderPlanSHA256 != intent.FounderPlanSHA256 || candidate.FounderPlanSHA256 != founderPlanDigest ||
		candidate.PeerRowDigest != intent.PeerRowDigest || candidate.PeerRowDigest != peerRowDigest ||
		candidate.ManifestDigest != intent.ManifestDigest || candidate.ManifestDigest != manifestDigest ||
		candidate.LaunchProfileDigest != intent.LaunchRequestDigest {
		return fmt.Errorf("%w: managed-peer candidate does not match the pinned launch intent", ErrRecordAuthorization)
	}
	return nil
}

func (ledger *Ledger) decodeManagedPeerProgress(scope BootstrapScope, body []byte,
	current bool,
) (ManagedPeerProgress, trust.Envelope, error) {
	envelope, payload, err := ledger.signedPayload(body, scope, domainBootstrapProgress, current)
	if err != nil {
		return ManagedPeerProgress{}, trust.Envelope{}, err
	}
	var progress ManagedPeerProgress
	if err := decodeCanonicalPayload(payload, &progress); err != nil || !progress.matches(scope, ledger.config.Environment) ||
		progress.SchemaVersion != 1 || progress.Attempt == 0 || progress.Generation == 0 || progress.Sequence == 0 ||
		!validDigest(progress.CandidateDigest) {
		return ManagedPeerProgress{}, trust.Envelope{}, fmt.Errorf("%w: managed-peer progress is malformed or outside its signed scope", ErrInvalidRecord)
	}
	switch progress.Phase {
	case ManagedPeerProgressCandidate:
		if progress.PendingProofKind != "" || progress.PendingProofDigest != "" || len(progress.PendingProofWire) != 0 {
			return ManagedPeerProgress{}, trust.Envelope{}, fmt.Errorf("%w: candidate progress cannot stage proof bytes", ErrInvalidRecord)
		}
	case ManagedPeerProgressReceipt, ManagedPeerProgressResult:
		wantKind := "receipt"
		if progress.Phase == ManagedPeerProgressResult {
			wantKind = "result"
		}
		if progress.PendingProofKind != wantKind || !validDigest(progress.PendingProofDigest) ||
			len(progress.PendingProofWire) == 0 || len(progress.PendingProofWire) > maxLedgerRecordBytes ||
			objectDigest(progress.PendingProofWire) != progress.PendingProofDigest {
			return ManagedPeerProgress{}, trust.Envelope{}, fmt.Errorf("%w: staged progress proof is incomplete or has a mismatched digest", ErrInvalidRecord)
		}
	default:
		return ManagedPeerProgress{}, trust.Envelope{}, fmt.Errorf("%w: unknown managed-peer progress phase %q", ErrInvalidRecord, progress.Phase)
	}
	return progress, envelope, nil
}

func (progress ManagedPeerProgress) matches(scope BootstrapScope, environment string) bool {
	return progress.DeploymentID == scope.DeploymentID && progress.Cell == scope.Cell &&
		progress.Environment == environment && progress.Role == roleController && progress.Slot == scope.Slot
}

func (ledger *Ledger) decodeRetirement(scope BootstrapScope, body []byte, current bool) (RetirementEvidence, trust.Envelope, error) {
	envelope, payload, err := ledger.signedPayload(body, scope, domainSlotRetirement, current)
	if err != nil {
		if envelope, payload, err = ledger.signedPayload(body, scope, domainSeedHandoff, current); err != nil {
			return RetirementEvidence{}, trust.Envelope{}, err
		}
	}
	var evidence RetirementEvidence
	if err := decodeCanonicalPayload(payload, &evidence); err != nil || !evidence.matches(scope, ledger.config.Environment) {
		return RetirementEvidence{}, trust.Envelope{}, fmt.Errorf("%w: retirement payload does not match signed scope", ErrRetirementInvalid)
	}
	now := ledger.now()
	if evidence.SchemaVersion != 1 || evidence.PreviousAttempt == 0 || evidence.PreviousGeneration == 0 ||
		!validDigest(evidence.PreviousResultDigest) || !isOCID(evidence.PriorInstanceOCID, "instance") ||
		evidence.PriorCreateKey == "" || !validDigest(evidence.ObservedEvidenceDigest) || evidence.FencingAuthority == "" ||
		evidence.ObservedAt.IsZero() || evidence.ObservedAt.Location() != time.UTC || evidence.ObservedAt.After(now.Add(ledger.config.TrustPolicy.ClockSkew)) ||
		current && now.Sub(evidence.ObservedAt) > ledger.config.TrustPolicy.MaxLifetime {
		return RetirementEvidence{}, trust.Envelope{}, ErrRetirementInvalid
	}
	if envelope.Scope.Domain == domainSeedHandoff {
		if evidence.Disposition != "seed-handoff" || !validDigest(evidence.CoordinatorHandoffDigest) {
			return RetirementEvidence{}, trust.Envelope{}, ErrRetirementInvalid
		}
	} else if evidence.Disposition != "instance-retired" || evidence.CoordinatorHandoffDigest != "" {
		return RetirementEvidence{}, trust.Envelope{}, ErrRetirementInvalid
	}
	return evidence, envelope, nil
}

// Material is one generation's renewable files and the keys behind them.
// Files may hold controller-<slot>.json, which Generation pins as configs.
type Material struct {
	Files                                                map[string][]byte
	OperatorID, SystemID, CellID, HostSignerID, SignerID string
	Operator, System, Cell, HostSigner, Signer           nkeys.KeyPair
	CA, ControllerIssuer                                 Authority
	// RoleSignerID is the role-scoped account signer.
	RoleSignerID string
	// Region is the cell token whose hosts the host issuer and scope serve;
	// New's is gru.
	Region string
}

// Certificate issues template under parent, or self-signed when parent is
// nil, and returns its authority, certificate PEM and key PEM.
func Certificate(t testing.TB, template *x509.Certificate, parent *Authority) (Authority, []byte, []byte) {
	t.Helper()
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	if template.SerialNumber == nil {
		template.SerialNumber, _ = rand.Int(rand.Reader, big.NewInt(1<<62))
	}
	signer, signerKey := template, key
	if parent != nil {
		signer, signerKey = parent.Certificate, parent.Key
	}
	der, err := x509.CreateCertificate(rand.Reader, template, signer, &key.PublicKey, signerKey)
	if err != nil {
		t.Fatal(err)
	}
	certificate, _ := x509.ParseCertificate(der)
	keyDER, _ := x509.MarshalECPrivateKey(key)
	return Authority{Certificate: certificate, Key: key}, pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der}),
		pem.EncodeToMemory(&pem.Block{Type: "EC PRIVATE KEY", Bytes: keyDER})
}

// CA is a CA template valid from an hour before now until notAfter.
func CA(name string, now, notAfter time.Time) *x509.Certificate {
	return &x509.Certificate{Subject: pkix.Name{CommonName: name}, NotBefore: now.Add(-time.Hour), NotAfter: notAfter,
		IsCA: true, BasicConstraintsValid: true, KeyUsage: x509.KeyUsageCertSign}
}

// ControllerIssuer is the controller TLS issuer template under a cell CA.
func ControllerIssuer(now, notAfter time.Time) *x509.Certificate {
	template := CA("TerraScale gru controller issuer", now, notAfter)
	template.MaxPathLenZero = true
	template.ExtKeyUsage = []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth}
	return template
}

// HostIssuer is the host TLS issuer template of cell gru, as hostenroll loads it.
func HostIssuer(now, notAfter time.Time) *x509.Certificate { return hostIssuer("gru", now, notAfter) }

func hostIssuer(region string, now, notAfter time.Time) *x509.Certificate {
	template := CA("TerraScale "+region+" host issuer", now, notAfter)
	template.MaxPathLenZero = true
	template.ExtKeyUsage = []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth}
	template.PermittedDNSDomainsCritical = true
	template.PermittedDNSDomains = []string{".hosts." + region + ".terrascale.internal"}
	template.PermittedURIDomains = []string{"hosts." + region + ".terrascale.internal"}
	return template
}

// New builds material valid for a year from now, for cell gru: a cell CA,
// controller and host issuers under it, and the operator, system and cell
// account JWTs with the host scope and a controller account signer.
func New(t testing.TB, now time.Time) Material { return NewCell(t, now, "gru") }

// NewCell is New for the cell whose token is region.
func NewCell(t testing.TB, now time.Time, region string) Material {
	t.Helper()
	operator, _ := nkeys.CreateOperator()
	system, _ := nkeys.CreateAccount()
	cell, _ := nkeys.CreateAccount()
	hostSigner, _ := nkeys.CreateAccount()
	return Rollover(t, now, Material{Operator: operator, System: system, Cell: cell, HostSigner: hostSigner, Region: region})
}

// Rollover builds a new CA, issuers and account signer for the NATS
// operator, system and cell accounts and host signer of previous.
func Rollover(t testing.TB, now time.Time, previous Material) Material {
	t.Helper()
	operator, system, cell, hostSigner, region := previous.Operator, previous.System, previous.Cell, previous.HostSigner, previous.Region
	year := now.AddDate(1, 0, 0)
	ca, caPEM, _ := Certificate(t, CA("TerraScale gru controller CA", now, year), nil)
	controllerIssuer, controllerCert, controllerKey := Certificate(t, ControllerIssuer(now, year.Add(-time.Hour)), &ca)
	_, hostCert, hostKey := Certificate(t, hostIssuer(region, now, year.Add(-time.Hour)), &ca)
	signer, _ := nkeys.CreateAccount()
	operatorID, _ := operator.PublicKey()
	systemID, _ := system.PublicKey()
	cellID, _ := cell.PublicKey()
	hostSignerID, _ := hostSigner.PublicKey()
	signerID, _ := signer.PublicKey()
	signerSeed, _ := signer.Seed()
	operatorClaims := jwt.NewOperatorClaims(operatorID)
	operatorClaims.SystemAccount = systemID
	operatorJWT, err := operatorClaims.Encode(operator)
	if err != nil {
		t.Fatal(err)
	}
	systemClaims := jwt.NewAccountClaims(systemID)
	systemClaims.Expires = year.Unix()
	systemJWT, _ := systemClaims.Encode(operator)
	cellClaims := jwt.NewAccountClaims(cellID)
	cellClaims.Expires = year.Unix()
	cellClaims.Limits.JetStreamLimits = jwt.JetStreamLimits{MemoryStorage: jwt.NoLimit, DiskStorage: jwt.NoLimit,
		Streams: jwt.NoLimit, Consumer: jwt.NoLimit}
	cellClaims.SigningKeys.AddScopedSigner(bootstrapmaterial.HostScope(region, hostSignerID))
	cellClaims.SigningKeys.Add(signerID)
	cellJWT, _ := cellClaims.Encode(operator)
	user, _ := nkeys.CreateUser()
	userID, _ := user.PublicKey()
	userSeed, _ := user.Seed()
	userClaims := jwt.NewUserClaims(userID)
	userClaims.Expires = year.Unix()
	userClaims.Pub.Allow = jwt.StringList{"$SYS.REQ.ACCOUNT." + cellID + ".CLAIMS.UPDATE"}
	userClaims.Sub.Allow = jwt.StringList{protocol.InboxGrant(region, userID)}
	userJWT, _ := userClaims.Encode(system)
	systemCreds, _ := jwt.FormatUserConfig(userJWT, userSeed)
	return Material{Files: map[string][]byte{
		"ca.pem": caPEM, "operator.jwt": []byte(operatorJWT + "\n"), "system.jwt": []byte(systemJWT + "\n"),
		"cell.jwt": []byte(cellJWT + "\n"), "system.creds": systemCreds,
		"host-tls-issuer-cert.pem": hostCert, "host-tls-issuer-key.pem": hostKey,
		"controller-tls-issuer-cert.pem": controllerCert, "controller-tls-issuer-key.pem": controllerKey,
		"controller-account-signer.seed": append(signerSeed, '\n'),
	}, OperatorID: operatorID, SystemID: systemID, CellID: cellID, HostSignerID: hostSignerID, SignerID: signerID,
		Operator: operator, System: system, Cell: cell, HostSigner: hostSigner, Signer: signer, Region: region,
		CA: ca, ControllerIssuer: controllerIssuer}.withRoleSigner(t)
}

func (material Material) Generation(expected bootstrap.MaterialGenerationExpectation, number uint64, previous string,
) bootstrap.MaterialGeneration {
	generation := bootstrap.MaterialGeneration{SchemaVersion: bootstrap.MaterialGenerationSchemaVersion,
		DeploymentID: expected.DeploymentID, Environment: expected.Environment, ClusterID: expected.ClusterID,
		Cell: expected.Cell, ControllerSlots: expected.ControllerSlots, Generation: number, Previous: previous,
		Operator: material.OperatorID, SystemAccount: material.SystemID, CellAccount: material.CellID,
		HostSigner: material.HostSignerID, AccountSigner: material.SignerID, RoleSigner: material.RoleSignerID}
	if material.SignerID != "" {
		generation.IssuedLifetimeHours = 24 * 7
	}
	for _, slot := range expected.ControllerSlots {
		if data, ok := material.Files["controller-"+slot+".json"]; ok {
			generation.ControllerConfigs = append(generation.ControllerConfigs, bootstrap.GenerationControllerConfig{
				Slot: slot, AcceptanceSHA256: digest([]byte("manifest of " + slot)), SHA256: digest(data), Size: int64(len(data))})
		}
	}
	for name, data := range material.Files {
		if strings.HasSuffix(name, ".json") {
			continue
		}
		purpose, slot := bootstrap.MaterialGenerationFiles()[name], ""
		if purpose == "" {
			purpose = bootstrap.SecretInterRegion
			for _, candidate := range expected.ControllerSlots {
				if name == candidate+".creds" {
					purpose, slot = bootstrap.SecretController, candidate
				}
				if cert, key := bootstrap.InterRegionTLSFiles(candidate); name == cert || name == key {
					slot = candidate
				}
			}
		}
		generation.Secrets = append(generation.Secrets, bootstrap.SecretReference{Purpose: purpose, Slot: slot,
			SecretOCID: fmt.Sprintf("ocid1.vaultsecret.oc1.sa-saopaulo-1.g%d-%s", number,
				strings.NewReplacer(".", "-", "_", "-").Replace(name)),
			VersionNumber: 1, SHA256: digest(data), MaxBytes: bootstrap.MaxSecretBytes, TargetFile: name})
	}
	return generation
}

// WithControllerCredentials adds offline-issued, slot-bound controller users
// and points each supplied config at its own credentials.
func (material Material) WithControllerCredentials(t testing.TB, slots []string) Material {
	t.Helper()
	files := map[string][]byte{}
	for _, slot := range slots {
		name := "controller-" + slot + ".json"
		var config struct {
			Version    int             `json:"version"`
			Controller map[string]any  `json:"controller"`
			NATS       natscell.Config `json:"nats"`
		}
		data, exists := material.Files[name]
		if !exists {
			t.Fatalf("WithControllerCredentials: slot %s has no %s", slot, name)
		}
		if err := json.Unmarshal(data, &config); err != nil {
			t.Fatalf("WithControllerCredentials: decode %s: %v", name, err)
		}
		config.NATS.CredentialsFile = bootstrap.MaterialDirectory + "/" + slot + ".creds"
		var ir *natscell.InterRegion
		if embedded := config.NATS.Embedded; embedded != nil {
			ir = embedded.InterRegion
		}
		home, err := ir.GlobalControlHome(config.NATS.Cell)
		if err != nil {
			t.Fatal(err)
		}
		globalHome := home == config.NATS.Cell
		user, _ := nkeys.CreateUser()
		public, _ := user.PublicKey()
		seed, _ := user.Seed()
		claim := jwt.NewUserClaims(public)
		claim.Expires = material.CA.Certificate.NotAfter.Unix()
		claim.Pub.Allow = natscell.ControllerPublishes("gru")
		if globalHome {
			claim.Pub.Allow.Add(natscell.GlobalControllerPublishes()...)
		}
		claim.Sub.Allow = jwt.StringList{protocol.InboxGrant("gru", public), protocol.Broker("gru", "ticket", ">"),
			protocol.Broker("gru", "fence", slot)}
		claim.Sub.Allow.Add(natscell.ControllerSubscriptions("gru")...)
		claim.Sub.Allow.Add(protocol.ObservabilityGrant("gru"))
		claim.Resp = &jwt.ResponsePermission{MaxMsgs: 1, Expires: 5 * time.Second}
		raw, err := claim.Encode(material.Cell)
		if err != nil {
			t.Fatal(err)
		}
		files[slot+".creds"], _ = jwt.FormatUserConfig(raw, seed)
		files[name], err = json.Marshal(config)
		if err != nil {
			t.Fatal(err)
		}
		clear(seed)
		user.Wipe()
	}
	return material.With(files)
}

func (material Material) WithoutIssuers(t testing.TB) Material {
	t.Helper()
	cell := material.Account(t, "cell.jwt", func(claims *jwt.AccountClaims) { delete(claims.SigningKeys, material.SignerID) })
	copied := material.With(map[string][]byte{"cell.jwt": cell})
	for _, name := range []string{"controller-tls-issuer-cert.pem", "controller-tls-issuer-key.pem",
		"controller-account-signer.seed"} {
		delete(copied.Files, name)
	}
	copied.SignerID, copied.Signer = "", nil
	return copied
}

// InterRegion adds cell gru's leaf fabric (TS-668) in the tree
// sfo <- gru <- fra, so gru both dials a parent and accepts a child:
// system.jwt and cell.jwt with the contract, interregion.jwt, the
