			DNSNames: []string{"leaf.gru.interregion.terrascale.internal"}, NotBefore: now.Add(-time.Hour), NotAfter: year,
			KeyUsage:    x509.KeyUsageDigitalSignature,
			ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth}}, &ca)
		leafTLS := natscell.TLSFiles{CAFile: directory + "interregion-ca.pem", CertFile: directory + certName,
			KeyFile: directory + keyName}
		config, err := json.Marshal(map[string]any{"version": roleconfig.Version, "controller": map[string]any{"candidate_id": slot},
			"nats": natscell.Config{Cell: "gru", Instance: slot, Embedded: &natscell.Embedded{
				CellJWTFile: directory + "cell.jwt", SystemJWTFile: directory + "system.jwt",
				InterRegion: &natscell.InterRegion{Peers: contract.Peers, GlobalHome: "sfo",
					AccountJWTFile: directory + "interregion.jwt", Subtrees: contract.Subtrees, Topology: &topology,
					Listen: &natscell.LeafListen{Host: "0.0.0.0", Port: 7422, TLS: leafTLS},
					Remotes: []natscell.LeafRemote{{Peer: "sfo", URLs: []string{"nats-leaf://10.1.0.10:7422"},
						ServerName:      "leaf.gru.interregion.terrascale.internal",

func (material Material) Read(name string) ([]byte, error) {
	data, ok := material.Files[name]
	if !ok {
		return nil, errors.New("missing")
	}
	return data, nil
}

// With copies the material with some files replaced.
func (material Material) With(files map[string][]byte) Material {
	copied := material
	copied.Files = map[string][]byte{}
	for name, data := range material.Files {
		copied.Files[name] = data
	}
	for name, data := range files {
		copied.Files[name] = data
	}
	return copied
}

func generationExpectation() bootstrap.MaterialGenerationExpectation {
	return bootstrap.MaterialGenerationExpectation{DeploymentID: "0000000000YY15F5R431V5JPJ9", Environment: "production",
		ClusterID: "00000000006GRRF84JEVN9TX7M", Cell: "GRU", ControllerSlots: []string{"controller-a", "controller-b", "controller-c"}}
}

func check(material generationtest.Material) (time.Time, error) {
	return bootstrapmaterial.CheckGenerationFiles(material.Generation(generationExpectation(), 1, ""), material.Read, time.Now())
}

func (generation MaterialGeneration) Validate() error {
	if _, err := generation.Cell.OCIRegion(); err != nil || generation.SchemaVersion != MaterialGenerationSchemaVersion ||
		!entityid.Valid(generation.DeploymentID) || !entityid.Valid(generation.ClusterID) ||
		generation.Environment != "production" && generation.Environment != "canary" ||
		len(generation.ControllerSlots) == 0 || len(generation.ControllerSlots) > 64 || generation.Generation == 0 ||
		generation.Generation > MaxMaterialGenerations ||
		generation.Generation == 1 && generation.Previous != "" ||
		generation.Generation > 1 && !sha256RE.MatchString(generation.Previous) ||
		!nkeys.IsValidPublicOperatorKey(generation.Operator) {
		return fmt.Errorf("%w: identity, schema or chain field", ErrMaterialGenerationInvalid)
	}
	accounts := []string{generation.SystemAccount, generation.CellAccount, generation.HostSigner, generation.RoleSigner}
	if generation.AccountSigner != "" {
		accounts = append(accounts, generation.AccountSigner)
	}
	for index, account := range accounts {
		if !nkeys.IsValidPublicAccountKey(account) || slices.Contains(accounts[:index], account) {
			return fmt.Errorf("%w: account keys must be distinct account keys", ErrMaterialGenerationInvalid)
		}
	}
	for index, slot := range generation.ControllerSlots {
		if !controllerSlotRE.MatchString(slot) || index > 0 && generation.ControllerSlots[index-1] >= slot {
			return fmt.Errorf("%w: controller slots must be sorted and distinct", ErrMaterialGenerationInvalid)
		}
	}
	seen := map[string]bool{}
	interregion, leaves, credentials := 0, 0, 0
	for _, secret := range generation.Secrets {
		purpose, slot, pinnable := generation.pinnable(secret.TargetFile)
		if !pinnable || seen[secret.TargetFile] || secret.Purpose != purpose || secret.Slot != slot ||
			secret.ValidateIdentity() != nil {
			return fmt.Errorf("%w: secret reference for %q", ErrMaterialGenerationInvalid, secret.TargetFile)
		}
		seen[secret.TargetFile] = true
		if purpose == SecretInterRegion {
			interregion++
		}
		if purpose == SecretController {
			credentials++
		}
		if strings.HasPrefix(secret.TargetFile, "leaf-") {
			leaves++
		}
	}
	issuers := 0
	for name, purpose := range MaterialGenerationFiles() {
		if purpose == SecretControllerIssuer && seen[name] {
			issuers++
		} else if !seen[name] && purpose != SecretControllerIssuer {
			return fmt.Errorf("%w: a generation pins every renewable file", ErrMaterialGenerationInvalid)
		}
	}
	// gru-1 and sfo-1 were founded without controller issuers (TS-668).
	issuing := issuers != 0
	if issuers != 0 && issuers != 3 || issuing != (generation.AccountSigner != "") ||
		issuing != (generation.IssuedLifetimeHours != 0) || generation.IssuedLifetimeHours < 0 ||
		generation.IssuedLifetimeHours > int(MaxIssuedLifetime.Hours()) {
		return fmt.Errorf("%w: the controller issuers, account signer and issued lifetime come all or none",
			ErrMaterialGenerationInvalid)
	}
	if credentials != 0 && (credentials != len(generation.ControllerSlots) || issuing || len(generation.ControllerConfigs) == 0) {
		return fmt.Errorf("%w: pinned controller credentials need every slot's config and credentials, without online issuers",
			ErrMaterialGenerationInvalid)
	}
	if interregion != 0 {
		// The interregion account comes with at most one parent's
		// credentials; a link has no account and at most its own.
		account := seen["interregion.jwt"]
		complete := seen["interregion-ca.pem"] && len(generation.ControllerConfigs) != 0 &&
			(account && leaves <= 1 && !seen[LinkCredentialsFile] || !account && leaves == 0)
		for _, slot := range generation.ControllerSlots {
			cert, key := InterRegionTLSFiles(slot)
			complete = complete && seen[cert] && seen[key]
		}
		if !complete {
			return fmt.Errorf("%w: interregion files need the CA, every slot's leaf TLS, the controller configs and "+
				"either the account with at most one parent's credentials or a link's credentials alone", ErrMaterialGenerationInvalid)
		}
	}
	if len(generation.ControllerConfigs) != 0 && len(generation.ControllerConfigs) != len(generation.ControllerSlots) {
		return fmt.Errorf("%w: controller configs must pin every controller slot", ErrMaterialGenerationInvalid)
	}
	for index, config := range generation.ControllerConfigs {
		if config.Slot != generation.ControllerSlots[index] || !sha256RE.MatchString(config.AcceptanceSHA256) ||
			!sha256RE.MatchString(config.SHA256) || config.Size < 1 || config.Size > MaxControllerConfigBytes {
			return fmt.Errorf("%w: controller config %d must pin slot %s's config once, in slot order",
				ErrMaterialGenerationInvalid, index, generation.ControllerSlots[index])
		}
	}
	return nil
}

// pinnable returns the purpose and slot under which a generation may pin
// name. The v1 contract adds the interregion or link files and slot credentials; interregion-ca.key and
// child-<cell>.seed are never pinnable.
func (generation MaterialGeneration) pinnable(name string) (SecretPurpose, string, bool) {
	if purpose, renewable := MaterialGenerationFiles()[name]; renewable {
		return purpose, "", true
	}
	parent, leaf := strings.CutPrefix(name, "leaf-")
	parent, creds := strings.CutSuffix(parent, ".creds")
	if name == "interregion.jwt" || name == "interregion-ca.pem" || name == LinkCredentialsFile ||
		leaf && creds && clusterRE.MatchString(parent) && parent != strings.ToLower(string(generation.Cell)) {
		return SecretInterRegion, "", true
	}
	for _, slot := range generation.ControllerSlots {
		if name == slot+".creds" {
			return SecretController, slot, true
		}
		if cert, key := InterRegionTLSFiles(slot); name == cert || name == key {
			return SecretInterRegion, slot, true
		}
	}
	return "", "", false
}

func CheckGenerationFiles(generation bootstrap.MaterialGeneration, read func(name string) ([]byte, error), now time.Time,
) (time.Time, error) {
	if err := generation.Validate(); err != nil {
		return time.Time{}, err
	}
	files := map[string][]byte{}
	for _, secret := range generation.Secrets {
		data, err := read(secret.TargetFile)
		if secret.Slot != "" && errors.Is(err, fs.ErrNotExist) {
			continue
		}
		if err != nil {
			return time.Time{}, fmt.Errorf("read %s: %w", secret.TargetFile, err)
		}
		digest := sha256.Sum256(data)
		if int64(len(data)) > secret.MaxBytes || hex.EncodeToString(digest[:]) != secret.SHA256 {
			return time.Time{}, fmt.Errorf("%w: %s differs from its pinned digest or size",
				bootstrap.ErrMaterialGenerationInvalid, secret.TargetFile)
		}
		files[secret.TargetFile] = data
	}
	configs := map[string][]byte{}
	for _, pin := range generation.ControllerConfigs {
		name := "controller-" + pin.Slot + ".json"
		data, err := read(name)
		if errors.Is(err, fs.ErrNotExist) {
			continue
		}
		if err != nil {
			return time.Time{}, fmt.Errorf("read %s: %w", name, err)
		}
		if int64(len(data)) != pin.Size || digest(data) != pin.SHA256 {
			return time.Time{}, fmt.Errorf("%w: %s differs from its pinned digest or size",
				bootstrap.ErrMaterialGenerationInvalid, name)
		}
		configs[pin.Slot] = data
	}
	cell := strings.ToLower(string(generation.Cell))
	check := generationCheck{now: now}
	roots := check.bundle("ca.pem", files["ca.pem"])
	// The v1 contract may pin no controller issuers; Validate ties them to
	// AccountSigner.
	issuing := generation.AccountSigner != ""
	if issuing {
		check.controllerIssuers(generation, files, roots)
	}
	if _, issuer, _, err := hostenroll.ParseTLSIssuer(files["host-tls-issuer-key.pem"], files["host-tls-issuer-cert.pem"],
		roots); err != nil {
		check.fail(err.Error())
	} else {
		domain := "hosts." + cell + ".terrascale.internal"
		if !issuer.PermittedDNSDomainsCritical || !slices.Equal(issuer.PermittedDNSDomains, []string{"." + domain}) ||
			!slices.Equal(issuer.PermittedURIDomains, []string{domain}) {
			check.fail("the host TLS issuer is not constrained to the cell's hosts")
		}
		check.certificate("host-tls-issuer-cert.pem", issuer)
	}
	operator, err := jwt.DecodeOperatorClaims(strings.TrimSpace(string(files["operator.jwt"])))
	// Decoding verifies each signature against the claim's issuer; the
	// issuer checks and DidSign tie those signers to the operator.
	if err != nil || operator.Subject != generation.Operator || operator.Issuer != generation.Operator ||
		!operator.DidSign(operator) || operator.SystemAccount != generation.SystemAccount || len(operator.SigningKeys) != 0 {
		check.fail("operator.jwt is not the operator's own JWT naming the system account, without signing keys")
		operator = nil
	} else {
		check.jwt("operator.jwt", operator.IssuedAt, operator.Expires)
	}
	system, err := jwt.DecodeAccountClaims(strings.TrimSpace(string(files["system.jwt"])))
	if err != nil || system.Subject != generation.SystemAccount || system.Issuer != generation.Operator ||
		operator == nil || !operator.DidSign(system) {
		check.fail("system.jwt is not the system account signed by the operator")
		system = nil
	} else {
		check.jwt("system.jwt", system.IssuedAt, system.Expires)
	}
	cellClaim, err := jwt.DecodeAccountClaims(strings.TrimSpace(string(files["cell.jwt"])))
	if err != nil || cellClaim.Subject != generation.CellAccount || cellClaim.Issuer != generation.Operator ||
		operator == nil || !operator.DidSign(cellClaim) {
		check.fail("cell.jwt is not the cell account signed by the operator")
		cellClaim = nil
	} else {
		hostScope, hostScoped := cellClaim.SigningKeys.GetScope(generation.HostSigner)
		keys := hostScoped && reflect.DeepEqual(hostScope, expectedHostScope(cell, generation.HostSigner))
		if issuing {
			accountScope, accountSigner := cellClaim.SigningKeys.GetScope(generation.AccountSigner)
			keys = keys && accountSigner && accountScope == nil
		}
		if generation.RoleSigner != "" {
			roleScope, roleScoped := cellClaim.SigningKeys.GetScope(generation.RoleSigner)
			keys = keys && roleScoped && reflect.DeepEqual(roleScope, roleidentity.Scope(generation.RoleSigner))
		}
		linked := natscell.VerifyLinkScope(cellClaim) == nil
		if !keys || len(cellClaim.SigningKeys) != 1+boolInt(issuing)+boolInt(generation.RoleSigner != "")+boolInt(linked) {
			check.fail("cell.jwt must have exactly the host scope, in v1 the role scope, with controller " +
				"issuers the unscoped account signer, and a link's signer as signing keys")
		}
		if cellClaim.Limits.JetStreamLimits == (jwt.JetStreamLimits{}) {
			check.fail("cell.jwt grants no JetStream")
		}
		check.jwt("cell.jwt", cellClaim.IssuedAt, cellClaim.Expires)
	}
	if err := natscell.ValidateSystemCredentials(files["system.creds"], cell, generation.CellAccount,
		generation.SystemAccount); err != nil {
		check.fail(err.Error())
	} else if raw, err := jwt.ParseDecoratedJWT(files["system.creds"]); err == nil {
		if user, err := jwt.DecodeUserClaims(raw); err == nil {
			check.jwt("system.creds", user.IssuedAt, user.Expires)
		}
	}
	check.interRegion(generation, files, configs, operator, system, cellClaim)
	if len(check.problems) != 0 {
		return time.Time{}, fmt.Errorf("%w: %s", bootstrap.ErrMaterialGenerationInvalid, strings.Join(check.problems, "; "))
	}
	return check.first, nil
}

// controllerIssuers checks the controller TLS issuer and the account signer.
func (check *generationCheck) controllerIssuers(generation bootstrap.MaterialGeneration, files map[string][]byte,
	roots []*x509.Certificate,
) {
	if issuer, err := controllerIssuer(files["controller-tls-issuer-key.pem"], files["controller-tls-issuer-cert.pem"],
		roots); err != nil {
		check.fail(err.Error())
	} else {
		check.certificate("controller-tls-issuer-cert.pem", issuer)
	}
	if signer, err := nkeys.FromSeed([]byte(strings.TrimSpace(string(files["controller-account-signer.seed"])))); err != nil {
		check.fail("controller-account-signer.seed is not an NKey seed")
	} else {
		public, _ := signer.PublicKey()
		signer.Wipe()
		if public != generation.AccountSigner {
			check.fail("controller-account-signer.seed is not the generation's account signer")
		}
	}
}

func (check *generationCheck) interRegion(generation bootstrap.MaterialGeneration, files, configs map[string][]byte,
	operator *jwt.OperatorClaims, system, cellClaim *jwt.AccountClaims,
) {
	pinned := map[string]bool{}
	for _, secret := range generation.Secrets {
		pinned[secret.TargetFile] = true
	}
	var interregion *jwt.AccountClaims
	if pinned["interregion.jwt"] {
		claim, err := jwt.DecodeAccountClaims(strings.TrimSpace(string(files["interregion.jwt"])))
		if err != nil || claim.Issuer != generation.Operator || operator == nil || !operator.DidSign(claim) ||
			!nkeys.IsValidPublicAccountKey(claim.Subject) || slices.Contains([]string{generation.SystemAccount,
			generation.CellAccount, generation.HostSigner, generation.AccountSigner, generation.RoleSigner}, claim.Subject) {
			check.fail("interregion.jwt is not an interregion account signed by the operator")
		} else {
			interregion = claim
			check.jwt("interregion.jwt", claim.IssuedAt, claim.Expires)
		}
	}
	if pinned["interregion-ca.pem"] {
		roots := x509.NewCertPool()
		for _, ca := range check.bundle("interregion-ca.pem", files["interregion-ca.pem"]) {
			roots.AddCert(ca)
		}
		// Another slot's pair is absent; half a pair fails as a mismatch.
		for _, slot := range generation.ControllerSlots {
			if cert, key := bootstrap.InterRegionTLSFiles(slot); files[cert] != nil || files[key] != nil {
				check.interRegionLeaf(cert, files[cert], files[key], roots)
			}
		}
	}
	if pinned[bootstrap.LinkCredentialsFile] {
		data := files[bootstrap.LinkCredentialsFile]
		if err := natscell.ValidateLinkCredentialBytes(data, strings.ToLower(string(generation.Cell))); err != nil {
			check.fail(bootstrap.LinkCredentialsFile + ": " + err.Error())
		} else if raw, err := jwt.ParseDecoratedJWT(data); err == nil {
			if user, err := jwt.DecodeUserClaims(raw); err == nil {
				check.jwt(bootstrap.LinkCredentialsFile, user.IssuedAt, user.Expires)
			}
		}
	}
	leafAccounts := map[string]string{}
	for name := range pinned {
		if strings.HasPrefix(name, "leaf-") {
			account, err := check.leafCredentials(name, files[name])
			if err != nil || interregion != nil && account == interregion.Subject {
				check.fail(name + " is not a leaf user of another region's interregion account without permissions of its own")
			}
			leafAccounts[name] = account
		}
	}
	contracts := 0
	for _, slot := range generation.ControllerSlots {
		if files[slot+".creds"] != nil && configs[slot] == nil {
			check.fail(slot + ".creds needs its controller config")
		}
		if data, supplied := configs[slot]; supplied &&
			check.controllerConfig(generation, slot, data, files, pinned, leafAccounts, system, cellClaim, interregion) {
			contracts++
		}
	}
	if pinned["interregion-ca.pem"] && contracts == 0 {
		check.fail("the interregion files need a controller config to check their contract against")
	}
}

func (check *generationCheck) controllerConfig(generation bootstrap.MaterialGeneration, slot string, data []byte,
	files map[string][]byte, pinned map[string]bool, leafAccounts map[string]string, system, cellClaim, interregion *jwt.AccountClaims,
) bool {
	name := "controller-" + slot + ".json"
	var top map[string]jsontext.Value
	var version int
	var nats natscell.Config
	if protocol.DecodeStrict(data, &top, bootstrap.MaxControllerConfigBytes) != nil ||
		protocol.DecodeStrict(top["version"], &version, bootstrap.MaxControllerConfigBytes) != nil || version != roleconfig.Version || top["controller"] == nil ||
		top["nats"] == nil || protocol.DecodeStrict(top["nats"], &nats, bootstrap.MaxControllerConfigBytes) != nil {
		check.fail(name + " is not a controller config")
		return false
	}
	if data := top["observability"]; data != nil {
		var telemetry observability.Config
		if protocol.DecodeStrict(data, &telemetry, bootstrap.MaxControllerConfigBytes) != nil || telemetry.Validate() != nil {
			check.fail(name + " has invalid observability settings")
			return false
		}
	}
	var ir *natscell.InterRegion
	var link *natscell.Link
	if nats.Embedded != nil {
		ir, link = nats.Embedded.InterRegion, nats.Embedded.Link
	}
	home, err := ir.GlobalControlHome(nats.Cell)
	if err != nil {
		check.fail(name + " has an invalid global home: " + err.Error())
		return false
	}
	if link != nil {
		home = natscell.LinkHome
	}
	var controller map[string]jsontext.Value
	if protocol.DecodeStrict(top["controller"], &controller, bootstrap.MaxControllerConfigBytes) != nil {
		check.fail(name + " has no controller settings")
		return false
	}
	if data := controller["global"]; data != nil {
		var global struct {
			Home string `json:"home"`
		}
		if protocol.DecodeStrict(data, &global, bootstrap.MaxControllerConfigBytes) != nil {
			check.fail(name + " has invalid global controller settings")
			return false
		}
		if global.Home != "" && global.Home != home {
			check.fail(name + " has a global home inconsistent with its interregion topology")
			return false
		}
	}
	if credsName := slot + ".creds"; pinned[credsName] {
		if nats.Cell != strings.ToLower(string(generation.Cell)) || nats.Instance != slot ||
			nats.CredentialsFile != filepath.Join(bootstrap.MaterialDirectory, credsName) || files[credsName] == nil {
			check.fail(credsName + " must be present and referenced at its installed path by its own cell and slot's config")
			return false
		}
		if err := CheckControllerCredentials(files[credsName], nats.Cell, slot, generation.CellAccount); err != nil {
			check.fail(credsName + ": " + err.Error())
		} else if raw, err := jwt.ParseDecoratedJWT(files[credsName]); err == nil {
			claim, err := jwt.DecodeUserClaims(raw)
			if err != nil {
				check.fail(credsName + ": " + err.Error())
			} else {
				check.jwt(credsName, claim.IssuedAt, claim.Expires)
			}
		}
		if home == nats.Cell {
			if err := natscell.ValidateGlobalControllerCredentialBytes(files[credsName]); err != nil {
				check.fail(credsName + ": " + err.Error())
			}
		}
	}
	if (ir != nil) != pinned["interregion.jwt"] || (link != nil) != (pinned["interregion-ca.pem"] && !pinned["interregion.jwt"]) {
		check.fail(name + " must reference interregion or link material exactly when the generation pins its files")
		return false
	} else if link != nil {
		return check.link(generation, slot, name, nats, pinned, cellClaim)
	} else if ir == nil {
		return false
	}
	contract, links, err := ir.Contract(nats.Cell)
	if err != nil || nats.Cell != strings.ToLower(string(generation.Cell)) {
		check.fail(name + " has no valid interregion block for this cell")
		return false
	}
	if system != nil && cellClaim != nil && interregion != nil {
		if err := contract.VerifyClaims(system, cellClaim, interregion, links); err != nil {
			check.fail("system.jwt, cell.jwt and interregion.jwt fail the interregion contract of " + name + ": " + err.Error())
		}
	}
	cert, key := bootstrap.InterRegionTLSFiles(slot)
	file := func(path, want string) bool {
		return path == filepath.Join(bootstrap.MaterialDirectory, want) && pinned[want]
	}
	tlsFiles := func(files natscell.TLSFiles) bool {
		return file(files.CAFile, "interregion-ca.pem") && file(files.CertFile, cert) && file(files.KeyFile, key)
	}
	pinnedOnly := file(ir.AccountJWTFile, "interregion.jwt") && file(nats.Embedded.CellJWTFile, "cell.jwt") &&
		file(nats.Embedded.SystemJWTFile, "system.jwt") && (ir.Listen == nil || tlsFiles(ir.Listen.TLS))
	dialed := map[string]bool{}
	for _, remote := range ir.Remotes {
		creds := "leaf-" + remote.Peer + ".creds"
		pinnedOnly = pinnedOnly && tlsFiles(remote.TLS) && file(remote.CredentialsFile, creds) &&
			remote.PeerAccount == leafAccounts[creds]
		dialed[creds] = true
	}
	for creds := range leafAccounts {
		pinnedOnly = pinnedOnly && dialed[creds]
	}
	if !pinnedOnly {
		check.fail(name + "'s interregion block references a file this generation does not pin, " +
			"or a remote account that did not issue its credentials")
	}
	return true
}

func (check *generationCheck) expires(name string, notAfter time.Time) {
	if !check.now.Before(notAfter) {
		check.fail(name + " has expired")
	}
	if check.first.IsZero() || notAfter.Before(check.first) {
		check.first = notAfter
	}
}

func (check *generationCheck) certificate(name string, certificate *x509.Certificate) {
	if check.now.Before(certificate.NotBefore) {
		check.fail(name + " is not yet valid")
	}
	check.expires(name, certificate.NotAfter)
}

// jwt checks a JWT was issued by now, within the trust envelope's clock
// skew, and records its expiry; zero means it never expires.
func (check *generationCheck) jwt(name string, issuedAt, expires int64) {
	if time.Unix(issuedAt, 0).After(check.now.Add(bootstrap.ManifestClockSkew)) {
		check.fail(name + " is issued in the future")
	}
	if expires != 0 {
		check.expires(name, time.Unix(expires, 0).UTC())
	}
}

func Generate(directory string, cfg Config, now time.Time) (Record, error) {
	if err := cfg.validate(); err != nil || !filepath.IsAbs(directory) || now.IsZero() || secureParents(directory) != nil {
		return Record{}, ErrMaterial
	}
	if _, err := os.Lstat(directory); err == nil {
		record, loadErr := Load(directory)
		if loadErr != nil || !sameConfig(record.Config, cfg) {
			return Record{}, ErrMaterial
		}
		return record, nil
	} else if !errors.Is(err, os.ErrNotExist) {
		return Record{}, ErrMaterial
	}
	if err := os.Mkdir(directory, 0o700); err != nil {
		return Record{}, fmt.Errorf("create private material directory: %w", err)
	}
	files, public, err := build(cfg, now.UTC())
	if err != nil {
		return Record{}, err
	}
	defer func() {
		for _, body := range files {
			clear(body)
		}
	}()
	record := Record{SchemaVersion: 1, Config: cfg, IssuedAt: now.UTC(),
		ExpiresAt: now.UTC().Add(time.Duration(cfg.ValidityHours) * time.Hour), Public: public}
	for name, body := range files {
		purpose, slot := classify(name)
		if purpose == "" || len(body) == 0 || len(body) > int(bootstrap.MaxSecretBytes) {
			return Record{}, ErrMaterial
		}
		record.Files = append(record.Files, File{Name: name, Purpose: purpose, Slot: slot,
			SHA256: digest(body), MaxBytes: int64(len(body))})
	}
	slices.SortFunc(record.Files, func(a, b File) int { return strings.Compare(a.Name, b.Name) })
	for _, file := range record.Files {
		if err := writeOnce(filepath.Join(directory, file.Name), files[file.Name]); err != nil {
			return Record{}, fmt.Errorf("write private material %s: %w", file.Name, err)
		}
	}
	metadata, err := json.Marshal(record)
	if err != nil {
		return Record{}, err
	}
	if err := writeOnce(filepath.Join(directory, metadataName), metadata); err != nil {
		return Record{}, err
	}
	if err := writeOnce(filepath.Join(directory, readyName), []byte(digest(metadata)+"\n")); err != nil {
		return Record{}, err
	}
	if err := syncDirectory(directory); err != nil {
		return Record{}, err
	}
	return record, nil
}

func CheckControllerCredentials(creds []byte, cell, slot, account string) error {
	if err := natscell.ValidateBrokerControllerCredentialBytes(creds, cell, slot); err != nil {
		return err
	}
	raw, err := jwt.ParseDecoratedJWT(creds)
	if err != nil {
		return err
	}
	claim, err := jwt.DecodeUserClaims(raw)
	if err != nil {
		return err
	}
	if !nkeys.IsValidPublicAccountKey(account) || claim.Issuer != account ||
		claim.IssuerAccount != "" && claim.IssuerAccount != account ||
		claim.Expires == 0 || claim.Expires <= claim.IssuedAt || claim.NotBefore != 0 ||
		!slices.Contains(claim.Sub.Allow, protocol.ObservabilityGrant(cell)) {
		return errors.New("controller credentials need the cell account signature, finite lifetime and local observability subscription")
	}
	allowed := natscell.ControllerPublishes(cell)
	allowed.Add(natscell.GlobalControllerPublishes()...)
	allowed.Add(natscell.GlobalControllerRequests()...)
	for _, grant := range claim.Pub.Allow {
		if !slices.Contains(allowed, grant) {
			return fmt.Errorf("controller credentials have unscoped publish %q", grant)
		}
	}
	for _, grant := range natscell.ControllerPublishes(cell) {
		if !slices.Contains(claim.Pub.Allow, grant) {
			return fmt.Errorf("controller credentials lack publish %q", grant)
		}
	}
	return nil
}

func credentialUserBytes(data []byte) (*jwt.UserClaims, string, error) {
	raw, err := nkeys.ParseDecoratedJWT(data)
	if err != nil {
		return nil, "", err
	}
	claim, err := jwt.DecodeUserClaims(raw)
	if err != nil {
		return nil, "", err
	}
	pair, err := nkeys.ParseDecoratedUserNKey(data)
	if err != nil {
		return nil, "", err
	}
	defer pair.Wipe()
	public, err := pair.PublicKey()
	if err != nil || public != claim.Subject {
		return nil, "", errors.New("regional credential seed and user JWT differ")
	}
	if claim.BearerToken || claim.ProxyRequired || len(claim.Src) != 0 ||
		len(claim.AllowedConnectionTypes) != 0 && !claim.AllowedConnectionTypes.Contains(jwt.ConnectionTypeInProcess) {
		return nil, "", errors.New("regional JWT depends on client metadata unavailable through the bridge")
	}
	return claim, public, nil
}

func ValidateBrokerControllerCredentialBytes(data []byte, cell, broker string) error {
	if !cellName.MatchString(cell) || !cellName.MatchString(broker) {
		return errors.New("broker controller credential cell or instance is invalid")
	}
	claim, public, err := credentialUserBytes(data)
	if err != nil {
		return fmt.Errorf("broker controller credentials: %w", err)
	}
	ticket := protocol.Broker(cell, "ticket", ">")
	fencePublish := protocol.Broker(cell, "fence", ">")
	fenceReceive := protocol.Broker(cell, "fence", broker)
	if !slices.Contains(claim.Pub.Allow, ticket) || !slices.Contains(claim.Pub.Allow, fencePublish) ||
		!slices.Contains(claim.Sub.Allow, ticket) || !slices.Contains(claim.Sub.Allow, fenceReceive) {
		return errors.New("broker controller credentials lack ticket or instance-bound fence grants")
	}
	allowedSubscriptions := map[string]bool{
		inboxPrefix(cell, public) + ".>": true,
		ticket:                           true, fenceReceive: true,
	}
	for _, subject := range ControllerSubscriptions(cell) {
		allowedSubscriptions[subject] = true
	}
	for _, subject := range GlobalControllerRequests() {
		allowedSubscriptions[subject] = true
	}
	// Optional read-only member telemetry (observability snapshots). The
	// issuer does not grant it today; it is accepted, not required.
	allowedSubscriptions[protocol.ObservabilityGrant(cell)] = true
	for _, grant := range claim.Sub.Allow {
		if !allowedSubscriptions[grant] {
			return fmt.Errorf("broker controller credentials have unscoped subscription %q", grant)
		}
	}
	if !slices.Contains(claim.Sub.Allow, inboxPrefix(cell, public)+".>") ||
		!slices.Contains(claim.Sub.Allow, protocol.BrokerClaimApplySubject(cell)) ||
		!slices.Contains(claim.Sub.Allow, protocol.ManagedUpdatePrepareSubject(cell)) ||
		!slices.Contains(claim.Sub.Allow, protocol.BackupOperationSubject(cell)) ||
		!slices.Contains(claim.Sub.Allow, protocol.TerminalSubject(cell, ">")) ||
		len(claim.Pub.Deny) != 0 || len(claim.Sub.Deny) != 0 ||
		claim.Resp == nil || claim.Resp.MaxMsgs != 1 ||
		claim.Resp.Expires <= 0 || claim.Resp.Expires > 5*time.Second {
		return errors.New("broker controller credentials need a private inbox and one bounded response grant")
	}
	return nil
}

func GlobalControllerPublishes() []string {
	return []string{protocol.Control(protocol.GlobalScope, ">"), protocol.GlobalState(">")}
}

// GlobalControllerRequests are the home's request subjects, which a home
// controller both sends and answers on its own cluster. Credentials issued
// before this grant lack it: the request gets no answer and the dashboard
// reports the global leader unavailable. The home still starts, so these are
// kept out of GlobalControllerPublishes, whose absence stops it.
func GlobalControllerRequests() []string { return []string{protocol.GlobalBudgetSetSubject()} }

func ValidateGlobalControllerCredentialBytes(data []byte) error {
	claim, _, err := credentialUserBytes(data)
	if err != nil {
		return err
	}
	return globalPublishGranted(claim.Pub.Allow, claim.Pub.Deny)
}

// globalPublishGranted checks JWT publish permissions against every global
// home namespace. An absent allow list means every subject not denied; a
// present one must cover the namespace. Any deny that can match a subject in
// the namespace makes a publish fail.
func globalPublishGranted(allow, deny []string) error {
	for _, subject := range GlobalControllerPublishes() {
		if len(allow) != 0 && !grantsCover(allow, subject) || grantsTouch(deny, subject) {
			return fmt.Errorf("%w: %q", ErrMissingGlobalGrants, subject)
		}
	}
	return nil
}

func loadIssuer(t *testing.T, material generationtest.Material) *bootstrapmaterial.ControllerIssuer {
	t.Helper()
	issuer, err := bootstrapmaterial.LoadControllerIssuer(material.Generation(generationExpectation(), 1, ""),
		material.Files["controller-tls-issuer-cert.pem"], material.Files["controller-tls-issuer-key.pem"],
		material.Files["controller-account-signer.seed"])
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(issuer.Wipe)
	return issuer
}

func LoadControllerIssuer(generation bootstrap.MaterialGeneration, certPEM, keyPEM, signerSeed []byte,
) (*ControllerIssuer, error) {
	return loadControllerIssuer(issuerIdentity{Cell: string(generation.Cell), Environment: generation.Environment,
		Operator: generation.Operator, CellAccount: generation.CellAccount, AccountSigner: generation.AccountSigner,
		lifetime: time.Duration(generation.IssuedLifetimeHours) * time.Hour}, certPEM, keyPEM, signerSeed)
}

func loadControllerIssuer(identity issuerIdentity, certPEM, keyPEM, signerSeed []byte) (*ControllerIssuer, error) {
	block, _ := pem.Decode(certPEM)
	if block == nil {
		return nil, errors.New("controller TLS issuer certificate is invalid")
	}
	cert, err := x509.ParseCertificate(block.Bytes)
	if err != nil {
		return nil, fmt.Errorf("controller TLS issuer certificate: %w", err)
	}
	if identity.expiresAt.IsZero() || cert.NotAfter.Before(identity.expiresAt) {
		identity.expiresAt = cert.NotAfter
	}
	keyBlock, _ := pem.Decode(keyPEM)
	if keyBlock == nil {
		return nil, errors.New("controller TLS issuer key is invalid")
	}
	key, err := x509.ParseECPrivateKey(keyBlock.Bytes)
	if err != nil {
		return nil, fmt.Errorf("controller TLS issuer key: %w", err)
	}
	signer, err := nkeys.FromSeed([]byte(strings.TrimSpace(string(signerSeed))))
	if err != nil {
		return nil, errors.New("controller account signer seed is invalid")
	}
	if public, err := signer.PublicKey(); err != nil || public != identity.AccountSigner {
		signer.Wipe()
		return nil, errors.New("controller account signer differs from the generation's")
	}
	return &ControllerIssuer{identity: identity, certPEM: pem.EncodeToMemory(block), cert: cert, key: key,
		signer: signer}, nil
}

func (issuer *ControllerIssuer) IssueFunctionTLS(admitted release.VerifiedFunction) (certPEM, keyPEM, issuerPEM []byte, err error) {
	return issuer.issueFunctionTLS(admitted, x509.ExtKeyUsageServerAuth)
}

// IssueFunctionClientTLS issues only the admitted tenant/function's client identity.
func (issuer *ControllerIssuer) IssueFunctionClientTLS(admitted release.VerifiedFunction) (certPEM, keyPEM, issuerPEM []byte, err error) {
	return issuer.issueFunctionTLS(admitted, x509.ExtKeyUsageClientAuth)
}

func (issuer *ControllerIssuer) issueFunctionTLS(admitted release.VerifiedFunction, usage x509.ExtKeyUsage) (certPEM, keyPEM, issuerPEM []byte, err error) {
	if issuer == nil || issuer.cert == nil || issuer.key == nil || !admitted.Valid() {
		return nil, nil, nil, errors.New("function TLS issuance requires a current admitted release and controller generation")
	}
	claim := admitted.Claim()
	now := time.Now()
	expires := minTime(minTime(admitted.ExpiresAt(), now.Add(time.Hour)), issuer.identity.expiresAt)
	if claim.Environment != issuer.identity.Environment || claim.Cell != issuer.identity.Cell ||
		now.Before(issuer.cert.NotBefore) || !now.Before(expires) {
		return nil, nil, nil, errors.New("function TLS release differs from the current controller generation")
	}
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, nil, nil, err
	}
	serial, err := rand.Int(rand.Reader, new(big.Int).Lsh(big.NewInt(1), 128))
	if err != nil {
		return nil, nil, nil, err
	}
	name := claim.FunctionID + "." + strings.ToLower(claim.TenantID) + ".functions." + strings.ToLower(claim.Cell) + ".terrascale.internal"
	template := &x509.Certificate{SerialNumber: serial, Subject: pkix.Name{CommonName: name},
		NotBefore: now.Add(-issuedBackdate), NotAfter: expires, KeyUsage: x509.KeyUsageDigitalSignature,
		ExtKeyUsage: []x509.ExtKeyUsage{usage},
		URIs:        []*url.URL{{Scheme: "spiffe", Host: "terrascale.tech", Path: "/tenants/" + claim.TenantID + "/functions/" + claim.FunctionID}}}
	if usage == x509.ExtKeyUsageServerAuth {
		template.DNSNames = []string{name}
	}
	der, err := x509.CreateCertificate(rand.Reader, template, issuer.cert, &key.PublicKey, issuer.key)
	if err != nil {
		return nil, nil, nil, err
	}
	keyDER, err := x509.MarshalECPrivateKey(key)
	if err != nil {
		return nil, nil, nil, err
	}
	defer clear(keyDER)
	return append(pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der}), issuer.certPEM...),
		pem.EncodeToMemory(&pem.Block{Type: "EC PRIVATE KEY", Bytes: keyDER}), bytes.Clone(issuer.certPEM), nil
}

func functionTLSProof(t *testing.T, tenant, function, cell, environment string, now time.Time, validFor time.Duration) release.VerifiedFunction {
	t.Helper()
	module := []byte("\x00asm\x01\x00\x00\x00")
	digest := sha256.Sum256(module)
	claim := release.FunctionClaim{Schema: release.FunctionSchema, ABI: release.FunctionABI, TenantID: tenant, FunctionID: function, Revision: "first",
		Digest: hex.EncodeToString(digest[:]), Bytes: int64(len(module)), Environment: environment, Cell: cell, Sequence: 1}
	root, rootKey, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	leaf, key, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	roots, err := trust.ParseKeyring(root)
	if err != nil {
		t.Fatal(err)
	}
	keyID, err := trust.KeyID(leaf)
	if err != nil {
		t.Fatal(err)
	}
	encoded, err := trust.EncodeDelegatedPublicKey(leaf)
	if err != nil {
		t.Fatal(err)
	}
	scope := release.FunctionScope(claim)
	delegation, err := trust.SignDelegation(trust.Delegation{SchemaVersion: trust.SchemaVersion, SubjectKeyID: keyID, SubjectPublicKey: encoded,
		Capabilities: []trust.Capability{{Domain: scope.Domain, DeploymentID: scope.DeploymentID, Cell: scope.Cell, Environment: scope.Environment,
			Role: scope.Role, Slots: []string{scope.Slot}, Actions: []string{"sign"}}}}, now.Add(-time.Minute), now.Add(validFor+time.Hour), rootKey)
	if err != nil {
		t.Fatal(err)
	}
	envelope, err := release.SignFunctionClaim(claim, module, delegation, roots, key, now, validFor)
	if err != nil {
		t.Fatal(err)
	}
	wire, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		t.Fatal(err)
	}
	delegationWire, err := trust.EncodeEnvelope(delegation)
	if err != nil {
		t.Fatal(err)
	}
	proof, err := release.VerifyFunctionCurrent(wire, delegationWire, module, roots, release.FunctionExpectation{Environment: environment, Cell: cell,
		TenantID: tenant, FunctionID: function, Revision: claim.Revision, Digest: claim.Digest, MinimumSequence: claim.Sequence}, now)
	if err != nil {
		t.Fatal(err)
	}
	return proof
}

func EncodePayload(value any) ([]byte, error) {
	encoded, err := json.Marshal(value, json.Deterministic(true))
	if err != nil {
		return nil, fmt.Errorf("encode trust payload: %w", err)
	}
	if err := validatePayload(encoded); err != nil {
		return nil, err
	}
	return encoded, nil
}

// Sign signs a strict, bounded JSON object for the exact supplied scope.
func Sign(payload []byte, scope Scope, issuedAt, expiresAt time.Time, privateKey ed25519.PrivateKey) (Envelope, error) {
	if len(privateKey) != ed25519.PrivateKeySize {
		return Envelope{}, fmt.Errorf("%w: invalid Ed25519 private key", ErrInvalid)
	}
	if err := scope.validate(); err != nil {
		return Envelope{}, err
	}
	compact, err := compactPayload(payload)
	if err != nil {
		return Envelope{}, err
	}
	issuedAt = issuedAt.Round(0).UTC()
	expiresAt = expiresAt.Round(0).UTC()
	if !validTime(issuedAt) || !validTime(expiresAt) || !expiresAt.After(issuedAt) {
		return Envelope{}, fmt.Errorf("%w: invalid trust validity interval", ErrInvalid)
	}
	publicKey := privateKey.Public().(ed25519.PublicKey)
	keyID, err := KeyID(publicKey)
	if err != nil {
		return Envelope{}, err
	}
	envelope := Envelope{
		SchemaVersion: SchemaVersion,
		KeyID:         keyID,
		Scope:         scope,
		IssuedAt:      issuedAt,
		ExpiresAt:     expiresAt,
		Payload:       compact,
	}
	material, err := signingMaterial(envelope)
	if err != nil {
		return Envelope{}, err
	}
	envelope.Signature = base64.RawURLEncoding.EncodeToString(ed25519.Sign(privateKey, material))
	return envelope, nil
}

// EncodeEnvelope emits the single deterministic JSON wire representation.
func EncodeEnvelope(envelope Envelope) ([]byte, error) {
	if err := envelope.validateShape(); err != nil {
		return nil, err
	}
	encoded, err := json.Marshal(envelope, json.Deterministic(true))
	if err != nil {
		return nil, fmt.Errorf("encode trust envelope: %w", err)
	}
	if len(encoded) > MaxEnvelopeBytes {
		return nil, fmt.Errorf("%w: encoded envelope exceeds size limit", ErrInvalid)
	}
	return encoded, nil
}

// DecodeEnvelope strictly decodes one canonical wire envelope. Unknown or
// duplicate fields, alternate outer JSON encodings, and oversized payloads fail.
func DecodeEnvelope(encoded []byte) (Envelope, error) {
	if len(encoded) == 0 || len(encoded) > MaxEnvelopeBytes {
		return Envelope{}, fmt.Errorf("%w: envelope is empty or too large", ErrInvalid)
	}
	var envelope Envelope
	if err := protocol.DecodeStrict(encoded, &envelope, MaxEnvelopeBytes); err != nil {
		return Envelope{}, fmt.Errorf("decode trust envelope: %w", err)
	}
	canonical, err := EncodeEnvelope(envelope)
	if err != nil {
		return Envelope{}, err
	}
	if string(canonical) != string(encoded) {
		return Envelope{}, fmt.Errorf("%w: envelope JSON is not canonical", ErrInvalid)
	}
	return envelope, nil
}

// VerifyCurrent verifies the exact scope, signature, lifetime, and current
// validity. Use this API before any current mutation or secret retrieval.
func VerifyCurrent(envelope Envelope, expected Scope, keys Keyring, now time.Time, policy Policy) ([]byte, error) {
	if !validTime(now) || policy.MaxLifetime <= 0 || policy.ClockSkew < 0 {
		return nil, fmt.Errorf("%w: invalid verification policy", ErrInvalid)
	}
	if err := verifySignature(envelope, expected, keys, policy.MaxLifetime); err != nil {
		return nil, err
	}
	if envelope.IssuedAt.Sub(now) > policy.ClockSkew {
		return nil, ErrNotYetValid
	}
	if !now.Before(envelope.ExpiresAt) {
		return nil, ErrExpired
	}
	return bytesClone(envelope.Payload), nil
}

// VerifyHistorical verifies scope, signature, key, and the bounded signed
// interval but deliberately makes no current-authorization claim.
func VerifyHistorical(envelope Envelope, expected Scope, keys Keyring, policy Policy) ([]byte, error) {
	if policy.MaxLifetime <= 0 || policy.ClockSkew < 0 {
		return nil, fmt.Errorf("%w: invalid verification policy", ErrInvalid)
	}
	if err := verifySignature(envelope, expected, keys, policy.MaxLifetime); err != nil {
		return nil, err
	}
	return bytesClone(envelope.Payload), nil
}

// SignDelegation signs root-controlled delegated key capabilities.
func SignDelegation(delegation Delegation, issuedAt, expiresAt time.Time, rootPrivateKey ed25519.PrivateKey) (Envelope, error) {
	if err := delegation.Validate(); err != nil {
		return Envelope{}, err
	}
	payload, err := EncodePayload(delegation)
	if err != nil {
		return Envelope{}, err
	}
	return Sign(payload, delegationScope(), issuedAt, expiresAt, rootPrivateKey)
}

// VerifyDelegationCurrent verifies a root-signed delegation and requires it to
// be currently valid before the key can authorize a current action.
func VerifyDelegationCurrent(envelope Envelope, roots Keyring, now time.Time, policy Policy) (VerifiedDelegation, error) {
	payload, err := VerifyCurrent(envelope, delegationScope(), roots, now, policy)
	if err != nil {
		return VerifiedDelegation{}, err
	}
	return decodeVerifiedDelegation(envelope, payload)
}

// VerifyDelegationHistorical validates the delegation signature and bounded
// interval without granting present-day authority.
func VerifyDelegationHistorical(envelope Envelope, roots Keyring, policy Policy) (VerifiedDelegation, error) {
	payload, err := VerifyHistorical(envelope, delegationScope(), roots, policy)
	if err != nil {
		return VerifiedDelegation{}, err
	}
	return decodeVerifiedDelegation(envelope, payload)
}

// VerifyDelegatedCurrent enforces current signer authority, key delegation
// validity, and exact capability scope.
func VerifyDelegatedCurrent(envelope Envelope, expected Scope, delegation VerifiedDelegation, now time.Time, policy Policy) ([]byte, error) {
	if !now.Before(delegation.expiresAt) || now.Add(policy.ClockSkew).Before(delegation.issuedAt) {
		return nil, ErrExpired
	}
	if err := delegation.authorize(expected); err != nil {
		return nil, err
	}
	if envelope.IssuedAt.Before(delegation.issuedAt) || envelope.ExpiresAt.After(delegation.expiresAt) {
		return nil, ErrDelegationTime
	}
	return VerifyCurrent(envelope, expected, Keyring{delegation.keyID: delegation.publicKey}, now, policy)
}

// VerifyDelegatedHistorical proves the key was delegated for the exact scope
// when the immutable record was signed; it does not authorize a new action.
func VerifyDelegatedHistorical(envelope Envelope, expected Scope, delegation VerifiedDelegation, policy Policy) ([]byte, error) {
	if err := delegation.authorize(expected); err != nil {
		return nil, err
	}
	if envelope.IssuedAt.Before(delegation.issuedAt) || envelope.ExpiresAt.After(delegation.expiresAt) {
		return nil, ErrDelegationTime
	}
	return VerifyHistorical(envelope, expected, Keyring{delegation.keyID: delegation.publicKey}, policy)
}
